(window.STORIES=window.STORIES||[]).push(...[{"n": 55, "l": "الجزء 27 | عام الحزن | الجزء 28 | رحلة الطائف", "u": "https://www.facebook.com/groups/710210019782034/permalink/780361906100178/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والعشرون\n#عام_الحزن\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما عمه أبو طالب مات وقريش ما صدقت واشتدت في الأذى على رسول الله ﷺ جدا،\nاجتمع على رسول الله ﷺ الأذى الجسدي والأذى النفسي، فكان إللي بيخفف عنه ويصبّره بعد ربنا هي زوجته خديجة\nكانت معاه من البداية،\nمن فترة شبابه لحد نزول الوحي، وفترة الجهر بالدعوة وشِعب أبي طالب،\nوجعلت كل أموالها تحت تصرف رسول الله ﷺ، \nيتصرف فيها زي ما هو عايز عشان تعينه على نشر دعوة الإسلام\nفخديجة كانت لها مكانة خاصة في قلب رسول الله ﷺ ومكانة خاصة عند رب العالمين ،\nلدرجة إن ربنا أرسل لها السلام مع جبريل ليخبرها به رسول الله ﷺ \nوربنا بشرها على لسان رسول الله ﷺ ببيت في الجنة من اللؤلؤ المجوف هادئ جدا مفهوش أي دوشة،\n\"عن أبي هريرة رضي الله عنه قال: \n\"أَتَىَ جِبْرِيلُ النّبِيّ ﷺ فَقَالَ: \nيَا رَسُولَ اللّهِ هَذِهِ خَدِيجَةُ قَدْ أَتَتْكَ، مَعَهَا إِنَاءٌ فِيهِ إِدَامٌ أَوْ طَعَامٌ أَوْ شَرَابٌ، \nفَإِذَا هِيَ أَتَتْكَ فَاقْرَأْ عَلَيْهَا السّلاَمَ مِنْ رَبّهَا عَزّ وَجَلّ، وَمِنّي، وَبَشِّرْهَا بِبَيْتٍ فِي الْجَنّةِ مِنْ قَصَبٍ لاَ صَخَبَ فِيهِ وَلاَ نَصَبَ\".\nمع إن الجنة أصلا هادئة ، لكن زيادة تخصيص لخديجة؛\nلأنها كانت دائما بتحافظ على هدوء البيت لرسول الله ﷺ عشان يرجع يرتاح فيه،\nلم يُذكر عنها إنها عملت مشكلة مع رسول الله ﷺ، ولا رفعت صوتها عليه ولم تُتعبه أبدا، و بالعكس كمان دي كانت بتساعده وتعينه،\nمع إن كان في فرص كثيرة للمشاكل بسبب الدعوة،\nلكن مع ذلك تحمّلت الأذى مع رسول الله ﷺ وصبرت،\nفبقت أفضل نساء أهل الجنة، فتخيلوا كانت امرأة صالحة أد إيه رضي الله عنها\nوخير متاع الدنيا المرأة الصالحة، فلما تكون امرأة بالصلاح ده ، زوجها هيحبها أد إيه،\nولو الزوج ده بقى رسول الله ﷺ هيبقى الحب عامل إزاي \nومع إن الزواج بأكثر من امرأة كان منتشر عادي في الجاهلية\nإلا إن رسول الله ﷺ لم يتزوج عليها أبدا خلال حياتها معاه إللي استمرت خمسة وعشرين سنة\nوده من تقديره لها عليه الصلاة والسلام، فهي أغنته عن أي امرأة وكانت له نعم الزوجة،\nفكان من وفائه لها وهو صاحب الخلق العظيم إنه لا يُكدر عليها الحياة بسبب الغيرة \nلكن مهما كان الإنسان بيحب شخص ومرتبط به فسنة الله في الكون لا تتبدل ولا تتغير،\nبعد موت أبي طالب بثلاثة أيام وفي رواية ثانية قيل شهر  ماتت خديجة رضي الله عنها\nبصفة عامة موت الزوجة بالنسبة للرجل بيبقى مصيبة ،وكل ما طالت العشرة كان الوضع أشد والفراق أصعب،\nفتخيلوا لما تكون زوجة زي خديجة رضي الله عنها وتموت،\nوكمان ماتت في أشد الأوقات على رسول الله ﷺ\nلسه رسول الله ﷺ مخرجش من حزنه على موت أبي طالب على الكفر،\nفربنا يبتليه بفقد السَّكَن، بفقد رفيقة عمره وأم أولاده\nماتت إللي كانت بتهوّن عليه وتعطيه الثقة لما يشتد عليه الأذى من قريش، ابتلاءات ورا بعض ورا بعض،\nورسول الله ﷺ في الإبتلاءات دي مكنش شاب صغير ده كان عنده خمسين سنة \nخمسين سنة وشايل هم المسلمين في الحبشة وهم المسلمين المستضعفين في مكة،\nوهم نشر الدعوة ده غير الأذى والإبتلاءات إللي بيتعرض لها هو نفسه شخصيا\nومع ذلك رسول الله ﷺ لم يعترض على قضاء الله، مقلش هو أنا ليه ربنا بيعمل معايا كده وأنا رسول،\nمقلش هو إيه الحكمة يعني إن ربنا يبتليني الإبتلاءات دي كلها،\nمقلش يارب كفاية أنا تعبت ومبقتش مستحمل ،\nبتسمعوا الكلام ده من الناس ولّا لأ، وابتلاءاتهم متجيش ذرة في ابتلاءات رسول الله ﷺ\nرسول الله كان بيحزن ،والحزن ده شيء طبيعي في النفس البشرية\nواحنا قلنا قبل كده إن الحزن لا يتعارض مع الصبر والرضا لما اتكلمنا في قصة يوسف عليه السلام ،\nلما يعقوب عليه السلام وهو نبي حزن لفقد يوسف وأخوه،\nالمشكلة مش في الحزن ،ده شيء طبيعي لكن المشكلة لما الحزن يخلي حياتنا تقف\nتلاقي البنت مامتها ماتت أو أبوها أو...أو... وتقول خلاص أنا حياتي وقفت ومش عارفة استمر في الحياة،\nوده سببه ضعف الإيمان، لازم نكون مستعدين نفسيا وإيمانيا  لفراق أي أحد عشان منتصدمش وحياتنا تقف\nأي حد بنحبه هنفارقه في يوم من الأيام،\nقال جبريل عليه السلام لرسول الله ﷺ: \n\"أحبب من شئت فإنك مُفارقه\"\n سواء أم أو أب أو جد أو ابن أو زوج أو زوجة أو...أو....\nزي ما حصل مع رسول الله ﷺ وربنا قالها لرسول الله ولنا:\n\"إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ \"\nرسول الله ﷺ هو أشد البشر بلاءًا على الإطلاق ، ومهما كانت ابتلاءاتنا فهو ابتلاءاته كانت أشد،\nومع ذلك حياته موقفتش ، كان بيحزن ويتألم لكن الحياة بتستمر،\nعنده دعوة لازم يوصلها لكل أهل الأرض، عنده أصحاب بيتعذبوا لازم يهون عليهم،\nرسول الله ﷺ عنده مسؤوليات، تخيلوا لو حزنه خلى حياته تقف!!\nكل حاجة هتضيع\nفمينفعش احنا كمان حياتنا تقف، عندنا مسؤوليات والتزامات سواء دينية أو نيوية \nوطبعا محدش يطلع ويقول أصل ده رسول الله ولازم يكون كده وهو ربنا مثبته\nلا يا جماعة رسول الله ﷺ بشر زينا بيحزن ويتألم وبيمرض وبيتعرض لنفس إللي احنا بنتعرض له\nوإلا مكنش ربنا يقول لنا نقتدي برسول الله ﷺ لو كان عنده قدرات خارقة مش عندنا \nعشان كده أي رسول لازم يكون بشر\n\"قُلْ إِنَّمَا أَنَا بَشَرٌ مِّثْلُكُمْ يُوحَىٰ إِلَيَّ أَنَّمَا إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ\"\nفلما حد يقولك رسول الله ﷺ عمل وانت كمان اعمل زيه متقولش أصل ده رسول الله ﷺ، أو حتى تقول جواك كده،\nلأن معنى كلامك إن ربنا قالك تعمل حاجة إنت مش أدها ومش هتقدر تعملها، \nوده كده ظلم، وربنا لا يظلم مثقال ذرة\nأيوة رسول الله ﷺ كان ربنا بيثبته بسبب قوة الإيمان إللي عنده،\nلكن قوة الإيمان دي حاجة مُكتسَبة \nيعني أي حد يقدر  يكون صاحب إيمان قوي وده عن طريق:\n♡طلب العلم الشرعي ،لأن كل ما الإنسان اتعرف على ربنا أكثر ،القلب يتملى حب وخوف ورجاء وخشية من الله،\nزي ما رسول الله ﷺ كان بيتعلم القرآن من جبريل\n♡الاجتماع على عمل الخير، تشوف حد تعمل معاه الطاعات المختلفة، ولو مفيش مش مشكلة استعينوا بالله وهتلاقوا ربنا بعث لكم إللي يعينكم\n♡الدعوة إلى الإيمان، يعني إنك تدعي الناس وتأمرهم بالمعروف وتنهاهم عن المنكر،\nكلموا الناس عن ربنا، وعن رسوله وعن الأخلاق، \nوقبل ما تكلمهم خليهم يشوفوا فيك فعلا الكلام ده، \nرسول الله ﷺ كان عبارة عن قرآن يمشي على الأرض، \nخلي ده هدفك، إنك عايز تكون قرآن يمشي على الأرض زيه،\nوطول مانت بتحاول إنك تكون كده؛\nعمرك ما هترجع عن طريق الإلتزام، لأنك هتكون كل يوم في زيادة،\nوده أهم حاجة ،إنك تستمر على طريق الإلتزام لحد ما تقابل ربنا \n♡التفكّر في الكون وفي الأحداث إللي بتحصل في حياتنا وحياة إللي حوالينا،\nونطلع العبر إللي تثبتنا على الدين وتقوّي إيماننا واحنا تكلمنا عن التفكر قبل كده في البداية قبل البعثة، \nممكن ترجعوا له لو حبيتم\n♡الصبر...مش هتقدر تعمل الحاجات إللي قلنا عليها دي غير لما يكون عندك صبر،\nصبر إنك تتعلم العلم الشرعي، صبر إنك تقعد وتتفكر ، صبر إنك تعمل الطاعات وتبعد عن المحرمات.\nطيب وإللي معندهوش صبر ضاع خلاص\nلا مضعش إللي معندهوش صبر يعلم نفسه الصبر مرة واتنين وعشرة لحد ما يوصل إنه يكون عنده صبر،\nورسول الله ﷺ بيقول :\n\"من يتَصبر يُصَبّره الله\"\nيعني إللي بيقاوم نفسه على الصبر ويغصبها عليه ربنا هيصبره،\nهو احنا مش لما بنيجي نصوم نبقى جعانين ونقعد نصبّر نفسنا ونستحمل لحد ما المغرب يأذن،\nأهه ربنا بيعلمنا طريقة الصبر، يعني هو أعطانا بداية الخيط، \nالصيام مثال على التصبّر وتعلم الصبر، \nطبقوا القاعدة دي في باقي حياتكم، صبروا نفسكم على الطاعة، وهتوصلوا في النهاية\n◇حياة رسول الله ﷺ  كلها عِبر، ومفيش بشر على وجه الأرض قصة حياته متوثّقة ومحفوظة بالدقة والتفاصيل دي غير رسول الله ﷺ،\nوده عشان نتبعه في كل خطوة من خطوات الحياة\nماتت خديجة في السنة العاشرة للبعثة، بعد موت أبي طالب، \nوالعلماء سمّوا العام ده بعام الحزن بسبب حزن رسول الله ﷺ الشديد على عمه وزوجته،\nيعني مش رسول الله ﷺ هو إللي سمى العام بعام الحزن\nالوضع دلوقتي في مكة نقدر نقول عنه إنه بقى متجمد، واقف زي ماهو مفيش أي تقدم\nالمسلمين بيعذبوا، المشركين بيؤذوا رسول الله ﷺ، محدش دخل في الإسلام، ودعوة الإسلام بتُحارب وتُشوّه\nحتى لما كان أي أحد ييجي للحج من سادات العرب كان سادات مكة بيحذروه إنهم يسمعوا لرسول الله ﷺ،\nوده من بداية الجهر بالدعوة، \nحتى في قصة حصلت مع سيد قبيلة دَوْس في حج السنة السادسة من البعثة،\nسيد دَوْس كان اسمه 《الطُّفَيْل بن عمرو الدَّوْسي》\nجاء للحج فلما سادة مكة شافوه قالوا له عندنا رجل ساحر، بيقول كلام سحر بيفرق بين الرجل وأهله والرجل وقبيلته،\nفاوعى تسمع له أبدا\nفبيقول الطُّفَيْل إنهم قعدوا يزنوا عليه لحد ماخاف وحط القطن في ودنه عشان ميسمعش كلام رسول الله ﷺ ولو بالغلط تخيلوا\nفوهو بيطوف حول الكعبة شاف رسول الله ﷺ بيصلي عند الكعبة،\nوطبعا كان شكله مميز لأنه بيصلي صلاة مختلفة عن باقي الناس، وكان قريب منه فأسمعه الله بعض كلمات من القرآن\nفلما رسول الله ﷺ خلّص صلاة وقام عشان يرجع بيته راح وراه الطفيل بن عمرو،\n☆سبحان الله الممنوع مرغوب \nيعني سادات مكة لو كانوا سابوه أو حتى كانوا قالوا له روح اسمع لمحمد مكنش هيروح، \nبس عشان همّ خوّفوه وقالوا متروحش أثاروا فضوله، \nوكل ما أي حد حاول يمنع دعوة الإسلام من الإنتشار وحاربها تنتشر أكثر \nراح له الطفيل وقال له يا محمد : \nقومك قالوا لي كذا وكذا وخوّفوني منك، لحد ما سديت أذني بالقطن\nوأنا سمعت بعض الكلام إللي قلته فأنا عايز أسمع منك \nفرسول الله ﷺ بدأ يوضح له رسالة الإسلام وقرأ عليه القرآن،\nفأسلم الطفيل بن عمرو الدوسي\nوبعدين في نفس اللحظة إللي أسلم فيها قال لرسول الله ﷺ :\nيارسول الله أنا سيد قومي، والناس بتسمع كلامي فأنا هروح أدعوهم للإسلام،\nلكن ادعوا الله إنه يجعل لي آية زي علامة كده تساعدني في دعوتهم\nفدعا له رسول الله ﷺ: يارب اجعل له آية\nفكان في وجهه زي نور كده ،كأنه مصباح مُضيء، \nفقال يا رسول الله: \nبلاش وجههي هيقولوا إن الآلهة عاقبته عشان ساب الدين\n فدعا رسول الله ﷺ له إنه يجعلها في طرف السوط بتاعه،\nفبقى الضوء متعلق في طرف سَوطه.\nفلما وصل لقبيلته دوس ودخل عليه أبوه وكان شيخ كبير في السن يسلم عليه قال له الطفيل:\nمتكلمنيش ولا لك أي علاقة بي خالص\nفأبوه استغرب وسأله: ليه يابني كده\nفقال له الطفيل: \nعشان أنا أسلمت وتابعت دين محمد \nفأبوه قال له: خلاص أنا ديني هو دينك \nفقال له الطفيل:\n روح اغتسل وطهر ملابسك وتعال أعلمك الإسلام، وفعلا عمل كده وعلمه وأسلم أبو الطفيل ،\nجاءت زوجته وقال لها: متكلمنيش ولا لك اي علاقة بي خالص\nفزوجته استغربت إيه ده في إيه\nفقال لها نفس الكلام فأسلمت هي كمان معاه، \nلقى الموضوع ماشي معاه كويس\nراح رايح لقومه وقال لهم نفس الكلام إللي قاله لأبوه وزوجته،\nطبعا مسمعوش كلامه وكانوا هيقتلوه ، وخلاص مش هنكلمك ولا لنا علاقة بك ، وهنجيب غيرك يعني بسيطة \nفراح لرسول الله ﷺ وقال له : يارسول الله محدش فيهم آمن وانتشر فيهم الزنا، \nادع عليهم يارسول الله\nفرفع رسول الله يده وقال:\nاللهم اهد دوسا \nفقال له : روح ادع قومك 《وارفق بهم》\n☆الطفيل بن عمرو كان مفكر إن الناس كلها زي بعض، وينفع معاها نفس الأسلوب،\nفلما استعمل أسلوب الشدة مع أهله ونجح،\nفكّر إن الأسلوب ده هينفع مع قومه\nونسي إن الأهل ممكن يتقبلوا منه إللي ميتقبلوش الغريب\nفمينفعش إننا ندعي الناس كلها بنفس الأسلوب، في ناس ممكن نتكلم معاهم بعشم فيقبلوا الكلام،\nفي ناس تانية بنتعامل معاهم بالشوكة والسكينة \nفي ناس إيمانها عالي مجرد ما نقول لهم قال الله وقال الرسول ينفذوا على طول بدون نقاش ،\nفي ناس تانية عايزة تقتنع الأول ونثبت لها صحة الكلام،\nوهكذا،\nفرسول الله ﷺ عرف إن الطفيل كان شديد على قومه، فوصّاه إنه يكلمهم براحة ورفق، مع إنهم كفار،\nفما بالنا لما بنتكلم وندعوا المسلمين، نعاملهم إزاي \nوكانت النتيجة إن دوس كلها أسلمت بعدين لما الطفيل دعاهم برفق\nالدعوة دلوقتي واقفة في مكة، مانعين حد يسمع لرسول الله ﷺ، \nمضيّقين على المسلمين في كل حاجة\nطيب وبعدين لازم يكون في حل وإلا كده مش هيبقى في أي تقدم خالص في الدعوة\nورسول الله ﷺ مهما كان حزين أو مهموم فهمه الأول هو نشر دعوة الإسلام\nرسول الله ﷺ فكّر في حاجة يعملها لأول مرة معملهاش خلال العشر سنين إللي فاتوا دول\nفكر إنه يطلع بنفسه خارج مكة يشوف مدينة تانية يدعو الناس إللي فيها،\nلكن المدينة إللي رسول الله ﷺ محتاجها، لها مواصفات معينة،\nرسول الله ﷺ فكر أنهي أكثر مدينة مناسبة ، لقاها مدينة الطائف\n☆اشمعنى الطائف\nمدينة الطائف كان لها مميزات مش موجودة في غيرها: \n◇أولا:\nتعتبر الطائف المدينة الثانية في الجزيرة العربية بعد مكة،\nفيها ناس كثيرة وفيها التجارة شغالة كويس، ولها مكانة بين قلوب العرب\n◇ثانيا:\nالطائف فيها قبيلة قوية جدا هي قبيلة ثقيف، وواضح من الأحداث إن الخطوة الجاية إللي قريش هتعملها هي إنها هتحارب رسول الله ﷺ والمسلمين،\nفاحنا محتاجين قبيلة قوية\n◇ثالثا:\nكان في منافسة دينية كبيرة بين مكة والطائف، فإذا كانت مكة فيها الصنم المشهور هُبل، \nفالطائف فيها صنم الَّلات المشهور وإللي ناس كثيرة بتحلف به،\nفيمكن الطائف تحب تسحب البساط من مكة فتتبنى هي الدعوة الجديدة دي وتتفوق على مكة\n◇رابعا:\nالطائف تعتبر قريبة نسبيا من مكة، المسافة بينهم مائة كيلو فقط،\nفكده هيبقى التنسيق سهل بين مكة والطائف، يعني رسول الله ﷺ هيعرف يتابع الأحداث في البلدين بسهولة\n◇خامسا:\nالطائف مهمة جدا لأهل مكة لأن أثرياء مكة لهم أملاك في الطائف،\nفلو دخلت الطائف في الإسلام هتكون ضربة اقتصادية كبيرة موجعة لأهل مكة \nرسول الله ﷺ أخذ القرار بإنه يتوجه للطائف، وكان ده بعد موت أبي طالب وخديجة بحوالي شهر،\nعلى حسب الروايات كان في شهر شوال من السنة العاشرة للبعثة تقريبا\nيعني رسول الله ﷺ معندوش حاجة اسمها راحة، مفيش راحة في الدعوة\nالمسافة بين مكة والطائف مائة كيلو،\nفخرج رسول الله ﷺ للطائف ماشي على قدمه\nوكان الطريق كله صحراء وحر ، كان في شهر مايو تقريبا،\nهو كان ممكن يأخذ معاه جمل أو فرس مثلا،\n بس لو كان عمل كده كان أهل مكة هينتبهوا إنه مسافر فممكن يمنعوه، وهو عايز ينشر الدعوة\nففَضّل إنه يتحمل مشقة السفر عشان يحاول إنجاح فكرة الدعوة في الطائف \nوحتى وهو مسافر لم يأخذ أحد من الصحابة الأقوياء زي حمزة أو عمر بن الخطاب،\nعشان برده محدش ياخد باله،أخذ معاه زيد بن حارثة، وكان ساعتها اسمه زيد بن محمد،\nفعادي لما واحد يخرج مع ابنه في مشوار\nقعد رسول الله ﷺ في الطريق حوالي يومين، لحد ما وصل للطائف.\nيا ترى هيبتدي الدعوة إزاي وهيكون إيه رد فعل أهل الطائف،\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الثامنة_والعشرون\n#رحلة_الطائف\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما خرج من مكة ومعاه زيد بن حارثة عشان يروح الطائف يدعو فيها الناس وتكون بديل لمكة،\nوصل رسول الله ﷺ للطائف بعد حوالي يومين من مشيه على قدميه في الصحراء،\nنحاول نحط نفسنا مكان رسول الله ﷺ ونفكر معاه هنبتدي إزاي\nخلونا نقف مع رسول الله ﷺ على باب مدينة الطائف،\nنبدأ إزاي ومنين، وندعوا مين \nوخصوصا إن الموضوع المرة دي مش مجرد دعوة للدخول في الإسلام فقط،\nلأ، ده دعوة وكمان رسول الله ﷺ هيطلب منهم إنهم ينصروه ضد قريش\nفاحنا محتاجين ناس لها وزن في البلد وكلمتها مسموعة،\nفهنروح لمين\nطبعا هنروح لسادات أهل الطائف، لأن دي مهمة سياسية مش هينفع فيها عوام الناس المستضعفين\nلأن المستضعفين مش هيقدروا يحموا رسول الله ﷺ ودعوة الإسلام من قريش،\nعايزين حد يتحمل المسؤولية ...له نفوذ ومكانته عالية بين الناس لما يقول الكلمة الناس بصفة عامة تسمع وتطيع،\nولأن رسول الله ﷺ ملوش حد يُجيره أو يحميه في الطائف،\nفمش هيقدر يدعو أي أحد إلا لما يكون في حماية له\nفذهب رسول الله ﷺ إلى ثلاثة إخوة وهم من سادات الطائف عشان يتكلم معاهم\n☆ممكن حد يسأل طيب ليه ربنا ميحمهوش ويؤيده بالمعجزات يعني وخلاص ،ماهو ربنا قادر \nقلنا قبل كده إن رسول الله ﷺ  قدوة، وحياته منهج ،وربنا أمرنا إننا نتبعه في كل حاجة،\nعشان كده رسول الله ﷺ لازم يأخذ خطوات عملية تنفع لأي أحد يأتي من بعده وهيكون في نفس الموقف بتاعه\nوحصل فعلا إن واحد من المسلمين اتحط في موقف شبيه بموقف رسول الله ﷺ، \nالموقف كان لواحد اسمه عبد الرحمن بن معاوية بن هشام بن عبد الملك، \nإللي اتعرف بإسم 《عبد الرحمن الداخل》 ، لما كان العباسيون بيقتلوا أي أحد من بيت الخلافة الأموية، \nهرب عبد الرحمن الداخل في قصة طويلة وكان مُطارد ومطلوب الرأس في كل مكان،\nلحد ما وصل للأندلس ، وقبل ما يدخل الأندلس كان أرسل مَولَاه لرؤساء قبائل البَرْبَر عشان يساعدوه في الدخول للأندلس، \nويقفوا معاه عشان يقدر يحكم الأندلس ويخلصها من الظلم إللي كانوا فيه ساعتها ويقيم الخلافة الأموية في الأندلس بعد سقوطها في المشرق،\nفده واحد من المسلمين استفاد من سيرة رسول الله ﷺ وتخطيطه للدخول للطائف\nوصل رسول الله ﷺ لسادات الطائف الثلاثة وعرّفهم بنفسه ودعاهم للإسلام وشرح لهم وضع المسلمين كله،\nوإنهم محتاجين الدعم والنصرة ضد قريش،\nهم كانوا ثلاثة إخوة أبناء واحد من سادات الطائف اسمه عمرو بن عُمير، خلونا نشوف ردوا على رسول الله ﷺ  قالوا إيه :\nالابن الأول كان اسمه عبد ياليل قال لرسول الله ﷺ:\nده أنا أقطع أستار الكعبة لو ربنا أرسلك \n《بيقول كده إعتراضا على ربنا يعني إزاي يرسلك إنت رسول\n》\nالابن الثاني وكان اسمه :مسعود قال:\nهو ربنا ملقاش غيرك يرسله يعني\nالابن الثالث كان اسمه حبيب، وده حاول يستظرف شوية \nقال:\nأنا مش هكلمك أبدا \nلو كنت رسول فأنت أعظم من إني أتكلم معاك\nولو كنت كاذب فأنت أحقر من إني أكلمك\nيعني كده كده مش هكلمك\nردودهم على رسول الله ﷺ كانت في قمة السفاهة وانعدام الأدب معاه\nتخيلوا نفسية رسول الله ﷺ  وهو بيسمع الكلام ده، والصدمة إللي اتصدمها من كلامهم\nومع ذلك رسول الله ﷺ قال لهم:\nطيب ده رأيكم ، بصوا متقولوش لأحد إننا حصل بيننا الكلام ده، خلوه سر بيننا!\nورسول الله ﷺ مش عايز الخبر يوصل لقريش، لأنهم لو عرفوا هيتهموه صراحة كده بالتخابر مع قبيلة أجنبية وإنه عايز يزعز نظام الحكم في مكة،\nوإنه عايز يثير الفتنة، ومش بعيد يأخذوها سبب عشان يقتلوا رسول الله ﷺ ويقولوا للناس ده خائن وتبقى قضية رأي عام بقى،\nوحتى الناس إللي كانوا متعاطفين معاه ينقلبوا ضده،\nوإنتم عارفين باقي القصة\nالثلاثة دول لم يحفظوا سر رسول الله ﷺ ، مكنش عندهم لا أخلاق ولا مروءة،\nمش بس أفشوا سر رسول الله ﷺ ، ده كمان حرّضوا السفهاء والغلمان على أذية رسول الله ﷺ \nرسول الله ﷺ لم ييأس وقعد في الطائف عشرة أيام مسبش واحد من أشرافهم إلا وكلمه، \nومحدش استجاب منهم إطلاقا وكلهم رفضوا دعوة الإسلام ونصرته ﷺ \nفي اليوم العاشر قالوا له: اخرج من بلدنا ،مش عايزينك فيها \nوعملوا صفين من العبيد والسفهاء خارج الطائف، \nولما أخرجوا رسول الله ﷺ جعلوه يعدي بين الصفين دول وبدأ العبيد والسفهاء يرموه بالحجارة وبدأ رسول الله ﷺ ينزف ،\nوهو مش عارف يتصرف إزاي،\nوكان معاه زيد بن حارثة بيحاول يبعد عنه الحجارة ومش عارف،\nالحجارة بتتحدف من كل مكان، واتفتحت رأس زيد رضي الله عنه، ده غير الشتيمة واللعن \nورسول الله ﷺ ومعاه زيد بيحاولوا إنهم يخرجوا من بين الصفين دول ،\nوحتى العبيد لم يتركوهما، طلعوا يجروا وراهم يحدفوهم بالطوب لمسافة كبيرة في روايات تقول قعدوا يجروا وراهم خمسة كيلو،\nلحد ما لقوا حديقة فدخل فيها رسول الله ﷺ ومعاه زيد حارثة،\nفخاف العبيد يدخلوا وراءهم ورجعوا للطائف،\nدخل رسول الله ﷺ وقعد في الحديقة دي وأسند ظهره لشجرة والدم ينزف منه من كل مكان\nمتخيلين نفسية رسول الله ﷺ كانت عاملة إزاي لما شوية عبيد وسفهاء يعملوا فيه كده وهو سيد من سادات مكة!!\nمتخيلين كمية الألم والوجع إللي كان حاسس بيهم في الوقت ده،\nوالدم بينزف من كل مكان، وهدومه مقطعة مليانة تراب وهو رجل عنده خمسين سنة ويتعمل فيه كده؟!!!\nرسول الله ﷺ شاف الدم وهدومه المقطعة والتراب ...حاول يتماسك قصاد زيد بن حارثة مقدرش،\nنزلت الدموع من عين رسول الله ﷺ ...قعد يبكي بحرقة،\nأيوة هو رسول لكنه بشر ...يتألم ..يحزن..ملوش أي مكان دلوقتي على الأرض،\nمكة... زمان الناس هناك عرفوا باللي حصل، \nالطائف... طردوه وضربوه وشتموه يروح فين طيب؟!!\nوأصلا ليه يحصل له كل ده..إيه السبب...ماهو كان عايش منعّم الناس كلها بتحترمه،\nوكان يُلقب بالصادق الأمين...كل إللي بيحصل ده بسبب دعوة الإسلام!!\nكل ده عشان كان عايز يوصل لنا الإسلام،\nواحنا أول حاجة بنفرط فيها هي سنة رسول الله ﷺ وتعاليم الإسلام،\nالناس مش عارفة التضحيات الرهيبة إللي دفعها رسول الله ﷺ والصحابة عشان يوصلوا رسالة الإسلام،\nالدين وصل لنا بالدم يا جماعة،\nهل بعد ده كله نفرط فيه كده بكل سهولة؟!!\nتخيلوا إحساس رسول الله ﷺ هيكون إيه لو سمع حد فينا بيقول على حاجة في الدين عادي يا جماعة دي سنة مش لازم نعملها \nالصحابة كانوا بيعملوا السنة عشان هي حاجة رسول الله ﷺ  عملها!!\nعارف لما تكون بتشتغل وطالع عينك في الشغل ومستحمل النزول في الحر والبرد،\nومستحمل موظفين معاك بيحرقوا دمك، ومدير قارفك في الشغل، كل ده عشان توفر لعيالك حياة كريمة وفي الآخر تيجي بنتك ولا ابنك يقولك: \nعادي يعني هو إنت بتعمل إيه، وياخد الفلوس ويصرفها في حاجات تافهة جدا\nإحساسك هيكون إيه ساعتها،\nولّا الأم تكون طول النهار طالع عينها في شغل البيت والجري ورا العيال والغسيل والطبخ و...و... وبعدين زوجها يقول لها وهو إنتِ بتعملي إيه أصلا،\nوعادي يعني إللي بتعمليه ده مش مهم\nاحساسها بيبقى عامل إزاي...حتى مفيش كلمة شكر تخفف عنها!!\nأهه احنا بنعمل كده مع رسول الله ﷺ  للأسف\nرسول الله اتعرض لأضعاف أضعاف إللي بنتعرض له عشان يوصل لنا الدين،\nواحنا حتى مش بنقول كلمة شكر في إننا نتبع سنته، ونقول تحقيرا 《دي سنُة》،\nمع إن السّنة دي مش اجتهاد من رسول الله ﷺ  ده ربنا هو إللي قال على الحاجات دي،\nيعني سنن الصلوات دي ربنا جعلها سنة، وجعل الفروض الخمسة فرض،\nرسول الله ﷺ مش بيجتهد في الدين بمزاجه، كل كلمة بيقولها ويعملها هي من عند الله\nاحنا أكيد زعلانين من إللي حصل لرسول الله ﷺ وكان نفسنا نبقى معاه عشان نحميه وننصره صح؟\nطيب ماحنا ممكن نعمل كده دلوقتي\nلو كل واحد فينا اتبع سنة رسول الله ﷺ  هو كده نصره،\nالحب مش مجرد كلمات ومشاعر....الحب أفعال،\nلو احنا متبعناش سنة رسول الله ﷺ دلوقتي واحنا آمنين، توقعوا إننا لو كنا في زمنه ﷺ ووسط تكذيب الناس له احتمال كبير أوي إننا كنا نكون مع الناس إللي كانت بتحدفه بالحجارة\nرسول الله ﷺ قعد يبكي بحرقة وضاقت عليه الدنيا ومفيش حد من أهل الأرض يقدر ينصره،\nفرفع يده إلى السماء...رفع يده لناصر المستضعفين والمظلومين، \nرفع يده لعالم الغيب والشهادة ...الذي يرى ويسمع كل شيء، دعا رسول الله ﷺ  بدعاء حزين جدا رُوِي أنه قال:\n\"اللهم إني أشكو إليك ضعف قوتي...وقلة حيلتي ...وهواني على الناس...يا أرحم الراحمين!\nأنت رب المستضعفين وأنت ربي...إلى من تَكِلُني؟ \nإلى بعيد يَتَجَهّمُنِي《يعني يكشر في وجهي》\nأم إلى عدو ملّكته أمري..إن لم يكن بك غضب عليّ فلا أبالي،\n《يعني يارب لو إللي بيحصلي ده مش بسبب إنك غضبان علي فأنا مش هيهمني، أهم حاجة إنك تكون راضي عني》\nلكن عافيتك أوسع لي..\nأعوذ بنور وجهك الذي أشرقت له الظلمات وصلُح عليه أمر الدنيا والآخرة من أن تنزل بي غضبك أو يحل عليّ سخطك،\nلك العُتْبى حتى ترضى ،ولا حول ولا قوة إلا بك\n 《يعني يارب أنا هقعد أعتذر لك لحد ما ترضى عني》\nرسول الله ﷺ دعا... نشوف استجابة ربنا وتخفيفه الألم عن رسول الله ﷺ هتيجي إزاي\n◇أولا :\nالحديقة إللي دخلها كانت لسيدين من سادات المكة إللي كانوا بيؤذوا رسول الله ﷺ، \nهما: شيبة وعتبة ابنا ربيعة، وكانوا ساعتها موجودين في الحديقة فشافوا رسول الله ﷺ وهو بالمنظر ده،\nالطبيعي إنهم يشمتوا فيه بسبب العداء إللي بينهم، ولكن ربنا رقق قلوبهم عليه،\n وبدل ما يشمتوا فيه أرسلوا عبد لهم اسمه عدّاس يعطيه قطف من عنب، كم عنقود عنب يعني،\nيبقى أول حاجة ربنا أرسل له طعام من عند أشد أعدائه\n◇ثانيا:\nبدأ رسول الله ﷺ يأكل من العنب وقال بسم الله، فاستغرب عداس إللي كان نصراني، أول مرة يسمع حد في المنطقة دي يقول كلمة بسم الله\nفقال عدّاس لرسول الله ﷺ: الكلام إللي قلته ده محدش بيقوله من أهل البلاد دي\nفقبل ما رسول الله ﷺ  يشرح لعداس يعني إيه بسم الله ويدعوه للإسلام بدأ يتعرف عليه،\n☆ودي قاعدة مهمة في الدعوة ...قبل ما تدعي حد اتعرف عليه الأول ،\nأو ابدأ بكلام بسيط لطيف تفتح منه الكلام،\nمتدخلش على طول في الشخص إللي قصادك وتقوله افعل ولا تفعل \nلأن احنا منعرفش إللي قصادنا ده كان يومه عامل إزاي، فممكن لو دخلنا فيه مرة واحدة كده يقفل أو يرد رد مش كويس،\nعشان كده نحاول نفتح حوار ولو بسيط مع الشخص إللي هندعوه، زي ما رسول الله ﷺ عمل مع عدّاس\nومع إن رسول الله ﷺ في حالة صعبة إلا إنه لم ينسَ أمر الدعوة،\nسادات الطائف رفضوا ،لكن لعل الغلام ده يُسلم، لعل رحلة الطائف كلها كانت عشانه\nبدأ رسول الله ﷺ يسأل عداس: \nإنت من أنهي بلد؟\nفقال عداس : من نَيْنَوى، فقال رسول الله ﷺ:\nمن قرية الرجل الصالح يونس بن متى؟\nفعداس استغرب وقال لرسول الله ﷺ:\nوإنت تعرف منين يونس بن متى\nأصلا نينوى قرية مش معروفة عند الناس، فده عارف القرية وعارف إن كان فيها نبي \nفرسول الله ﷺ قال له: هو أخي..أنا نبي وهو نبي!\nهنا عداس آمن في لحظة وقام على رسول الله ﷺ  يقبل رأسه ويده\nوعتبة وشيبة بيراقبوا الموقف من بعيد ...قالوا لبعض:\nبعتنا له الأكل أفسد علينا الغلام\nفنادوا على عداس فجاءهم وسألوه :\nهو إيه إللي حصل ده...إيه إللي خلّاك تقوم وتقبل محمد بالطريقة دي\nفقال لهم عداس :\nوالله مفيش أحد على الأرض أحسن من الرجل ده، والله قال لي حاجة محدش يعرفها غير نبي\nفقالوا : \nويحك يا عداس 《يعني كأنهم بيقولوا له نهارك أبيض \n》ده دينك أحسن من دينه، ملكش دعوة بيه\nفربنا هوّن على قلب رسول الله ﷺ بإسلام العبد الضعيف ده\nكان لازم رسول الله ﷺ يخرج من الحديقة دي لأنه لا يأمن على نفسه، ممكن أي أحد يؤذيه،\nفخرج متجها لمكة وهو لسه مهموم وعمال يفكر في حل،\nوفضل ماشي في اتجاه مكة ومكنش حاسس بنفسه، لحد ما وصل منطقة اسمها قرن الثعالب،\n يعني مشي خمسة وثلاثين كيلو من غير ما يشعر من شدة الهموم والتفكير \n◇ولما وصل لقرن الثعالب لقى في سحابة بتظله رفع رأسه لقى جبريل،\nوده الأمر الثالث من استجابة ربنا لدعاء رسول الله ﷺ، \nقال جبريل عليه السلام لرسول الله ﷺ:\nإن ربك سمع الكلام إللي الناس قالوه لك وردهم عليك،\nفأرسل الله لك معي ملك الجبال تأمره إللي إنت عايزه وهو هينفذ\nفنادى ملك الجبال رسول الله ﷺ وقال:\nيا محمد! لو إنت عايز ..هطبق عليهم الجبلين وهم في النص ويهلكوا جميعا \nعايزاكم تتخيلوا موقف رسول الله ﷺ \nربنا بنفسه أرسل له ملك الجبال عشان ينتقم من الناس إللي ظلموه، \nيعني هم فعلا يستحقوا الهلاك بإذن من الله،\nيعني رسول الله ﷺ  لو أمر ملك الجبال إنه يهلكهم ليس عليه أي لوم\nولكنه ﷺ رد بكل هدوء ورحمة وأخلاق راقية قال:\nلا...بل أرجو أن يُخرج الله عز وجل من أصلابهم من يعبد الله وحده\nيعني لو الناس دي كانوا مشركين لعل أبنائهم يؤمنوا.\n♡وده يعلمنا حاجة مهمة جدا وهي إننا كمسلمين رسالتنا إننا نجعل الناس مسلمين،\nمش ننتقم منهم، رسالتنا إننا ننقذهم من النار مش ندخلهم فيها، مش لازم يحصل التمكين للمسلمين على جثث الملايين من الكفار، \nمفيش مشكلة إن التمكين يتأخر في مقابل إسلام الكفار،\nالإسلام مش دين انتقام،\nالإسلام دين رحمة، الإسلام جاء عشان يرفع الظلم عن المظلومين،\nرسالتنا كمسلمين إننا نعلم الناس الدين بكل رحمة،\nوالناس مش هتسيبنا...الناس هتؤذينا وهتضايقنا و...و...\nبس ده مش سبب إننا نسيب الدعوة أبدا، لأن أجرنا بنأخذه من الله يوم القيامة\nمحدش يستهين بكلمة يقولها وهو يبتغي بها وجه الله،\nممكن تقول لواحدة نصيحة فيسخر منك،\nويروح ينقل الموقف لواحد تاني خالص على سبيل السخرية والاستهزاء بيك،\nتلاقي إللي وصله الكلام يهتدي بسبب نصيحتك، وإنت زعلان ومتعرفش ربنا بيدبر الأمور إزاي،\nعلى الرغم من إن رحلة الطائف كان كلها ألم نفسي وجسدي،\nلكن كان من ثمارها إسلام نفس ونجاتها من النار\nمتسيبوش الدعوة ...\nدعوة الناس للإلتزام، والدعوة للإسلام..ده الميراث إللي رسول الله ﷺ  تركه لنا وأوصله لنا بالدم،\nإللي عايز ينصر رسول الله ﷺ يتبعه ويتبع سنته ويعلمها لكل إللي حواليه،\nولو أوذيتم قولوا:\nلقد أُوذي رسول الله ﷺ بأكثر من هذا فصبر \nتمسكوا بسنة رسول الله ﷺ دي وصيته.. بيقول لكم :\nعليكم بسنتي وسنة الخلفاء الراشدين من بعدي عُضّوا عليها بالنواجذ ،\nيعني تمسكوا بها بقوة، متسيبوهاش...لازم بعد ما عرفنا إللي حصل مع رسول الله ﷺ في الطائف يكون لنا وقفة مع نفسنا،\nقول لنفسك دايما : اوعى تسيب سنة..تمسك بالسنة .. دي وصية رسول الله ﷺ..وصّلها لنا بالدم \nرجع جبريل وملك الجبال من غير ما يحصل حاجة، وكمل رسول الله ﷺ طريقه للرجوع لمكة، \nفي الطريق حصل حاجة عجيبة وجديدة من نوعها مع رسول الله ﷺ \nلكن قبل ما نعرف إيه إللي حصل، في سؤال وهو :\nإزاي ربنا يأذن لملك الجبال بتدمير مكة والطائف وفيهم ناس لم يؤذوا رسول الله ﷺ، \nيعني مش كل الناس آذوا رسول الله ﷺ ، فإيه ذنب الناس الذين لم يؤذوه\nهنعرف الإجابة على السؤال ده، مع الحادثة إللي حصلت لرسول الله ﷺ وهو راجع من مكة الجزء الجاي إن شاء الله"}, {"n": 56, "l": "الجزء 29 | إسلام نفر من الجن | والجزء 30 | هم الدعوه", "u": "https://www.facebook.com/groups/710210019782034/permalink/780379719431730/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_التاسعة_والعشرون\n#إسلام_نفر_من_الجن\nكنا واقفين المرة إللي فاتت عند سؤال مهم وهو إزاي ربنا يَأذن لملك الجبال بتدمير مكة والطائف وفيهم ناس لم يؤذوا رسول الله ﷺ، \nيعني مش كل الناس آذوا رسول الله ﷺ ، فإيه ذنب الناس الذين لم يؤذوه\nساعات بعض الناس بيعملوا حاجات غلط، وإللي حواليهم راضيين،\nأو شجعوهم على كده ، فاللي راضيين وشجعوا بيشاركوا الناس إللي عملت الخطأ في الإثم،\nحتى لو في واحد مش موجود واتحكى له ومأنكرش الغلط ورضِي به ، كان له نفس ذنب إللي عمل كده، فربنا يعاقبه زي إللي عمل\nقال رسول الله ﷺ :\n\" إذا عُمِلت الخطيئةُ في الأرض كان مَن شَهِدَها فكرهها\n – أو أنكرها – كمن غاب عنها، ومن غابَ عنها فَرَضِيَها، كان كمن شَهِدها\"\nزي مثلا إللي حصل مع ناقة صالح عليه السلام ..فاكرين\nالتسعة إللي كانوا مفسدين شجعوا الرجل إللي قتل الناقة،\nوالعذاب نزل على القرية كلها، لأنهم كانوا راضيين بقتلها \nمثال من أرض الواقع بتاعنا، لو واحد صاحبك راح فرح كله اختلاط وأغاني وقعد يحكيلك ويقولك عملنا وسوينا وحصل وحصل،\nفانت لو قلت له ياريتني كنت معاك، أو زعلت إنك مرحتش أو مأنكرتش على صاحبك ورضيت إللي هو عمله وإللي حصل في الفرح من المحرمات دي...هتاخدي نفس ذنب صاحبك مع إنك محضرتش\nلو واحدة بتحكيلك عن علاقتها المحرمة مع شاب وإنتِ بتسمعي ومبسوطة وراضية وبتشجعيها على الغلط ده،\nهتاخدي نفس ذنبها حتى لو إنتِ عمرك ما كلمتي شاب\nلو واحدة حكت لك إنها مسكت فلانة ومسحت بكرامتها الأرض ،وفرجت الدنيا عليها وإنتِ قلتي لها جدعة وتستاهل و...و....\nهتاخدي نفس ذنب إللي حكت لك مع إنك مكنتيش موجودة\nقيسوا بقى على كده...إللي يُقتل ظلم مثلا والناس ترضى وتشمت فيه تاخد نفس وزر القاتل، وهكذا...\nأي خطيئة تتعمل في أي مكان الأرض والناس ترضى عنها هياخدوا نفس ذنب إللي عملها\nشوفتوا إنكار المنكر بالقلب مهم إزاي\nوده يودينا لنقطة مهمة وهي إن الناس لو تركوا الأمر بالمعروف والنهي عن المنكر ومحاولات الإصلاح ربنا يعذب الجميع، الصالح وغير الصالح\nربنا بيقول:\n\"وَاتَّقُوا فِتْنَةً لا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ\"\nورسول الله ﷺ قال:\n\"إن الناس إذا رأوا الظالم فلم يأخذوا على يديه، أوشك أن يعمهم الله بعقابه\"\n فأهل الطائف استحقوا كلهم العذاب لأنهم إما وافقوا على أذى رسول الله ﷺ أو شجعوا أو فعلا آذوا رسول الله ﷺ، \nوربنا عالم بحال كل واحد فيهم،\n فلما يأذن بإهلاكهم جميعا معنى كده إنهم فعلا يستحقوا الهلاك ، وخصوصا إن ربنا لا يظلم مثقال ذرة\nرجع رسول الله ﷺ لمكة وقبل وصوله وهو في وادي نخلة حصل معاه حادثة،\nرسول الله ﷺ كان بيمشي وبعدين يقف يريّح،\nوراحته كانت إنه يصلي ركعتين \nوقف عشان يصلي، وهو بيصلي كان بيقرأ القرآن بصوت عالي،\nفمين إللي كان معدي وسمع رسول الله ﷺ بيقرأ القرآن\nسبع أفراد من الجن\nإيه إللي جابهم المكان ده أصلا\nلهم قصة \nبين زمن عيسى وزمن بعثة رسول الله ﷺ كانت الجن بيطلعوا عند السماء بيسترقوا السمع يعني بيتصنتوا على أهل السماء،\nعشان يعرفوا بعض من أخبار الغيب ويقولوها للكهان،\nوكانوا متعوّدين على كده ومفيش مشاكل، وفجأة اتمنعوا من استراق السمع\n\"وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا\"\nلقوا السماء اتملت ملائكة كثيرة يحرسوها،\nومعاهم الشهب المُحرقة يقذفوها على أي واحد فيهم يحاول إنه يقرب من السماء، إللي يقرب يلاقي شهاب يُقذف عليه يحرقه\n\"وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ فَمَنْ يَسْتَمِعِ الْآنَ يَجِدْ لَهُ شِهَابًا رَصَدًا \"\nفلما اتمنعوا فجأة كده قالوا أكيد حاجة حصلت في الارض\nوهم مكنوش عارفين إللي حصل ده هل بسبب إن ربنا يريد إنه ينزّل عذاب بأهل الأرض ولّا يريد لهم الخير\n\"وَأَنَّا لَا نَدْرِي أَشَرٌّ أُرِيدَ بِمَنْ فِي الْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا\"\nفقعدوا يدوّروا عن السبب لحد ما لقوا رسول الله ﷺ واقف يصلي في وادي نخلة،\nفسمعوه وهو بيقرأ فقالوا لبعض أنصتوا..اسمعوا كده\nفقربوا من رسول الله ﷺ عشان يسمعوا كويس ومن شدة قربهم منه كانوا كأنهم بيطلعوا على بعض\n\"وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ كَادُوا يَكُونُونَ عَلَيْهِ لِبَدًا \"\nدلوقتي رسول الله ﷺ ميعرفش حاجة خالص،\nهو بيصلي زي ما بيصلي عادي، \nوالجن احنا قلنا عنهم قبل كده في قصص الأنبياء إنهم عالم زينا بالضبط بياكلوا ويشربوا ويتناسلوا ويموتوا،\nوقلنا إن الشيطان هو الكافر من الجن، والعفريت هو المارد شديد القوة والدهاء والخبث\nواحنا لا نراهم إلا لو تمثلوا في صورة شخص أو حيوان مثلا ،\nفهم دلوقتي قريبين جدا من رسول الله ﷺ  بيسمعوا  القرآن ورسول الله ميعرفش عنهم حاجة\nوكان الجن متعجبين جدا من كلام القرآن ومن فصاحته \n\"وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا ۖ\"\nفآمن الجن ورجعوا لقومهم يدعوهم للإيمان \nمجرد ما سمعوا القرآن على طول من غير ما أي أحد يطلب منهم راحوا يدعوا قومهم عشان يسلموا،\n\"فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ\"\n☆طبعا السؤال إللي يطرح نفسه هنا هم الجن لغتهم إيه وفهموا القرآن إزاي\nالجن عالم زيينا بالضبط ، عندهم لغات برده، فيهم إللي بيفهم ويتكلم العربي وفيهم الإنجليزي والفرنسي ، فيهم كل الأجناس\n\"كُنَّا طَرَائِقَ قِدَدًا \"\nوفيهم السني والشيعي والصوفي والمرجئة ...كل الفرق برده\nوفيهم علماء وفيهم طلبة علم، وفيهم الصالحون والفجار،\nزي عالمنا بالضبط\n\"وأنا منا المسلمون ومن القاسطون\"\nوفيهم الكفار إللي بينكروا البعث زي الكفار من الإنس،\n\"وَأَنَّهُمْ ظَنُّوا كَمَا ظَنَنْتُمْ أَنْ لَنْ يَبْعَثَ اللَّهُ أَحَدًا \"\n《مصدر الكلام : كتاب : طريق الهجرتين لابن القيم،  وفتاوى الشيخ ابن باز》\nفبعد ما الجن سمعوا القرآن رجعوا لقومهم مُنذرين، يعني يخبروهم بأمر رسول الله ﷺ  والقرآن.\n☆وفي قول بيقول إن الجن كان فيهم رسل وأنبياء زي ما قلنا قبل كده،\nلكن رأي جمهور العلماء إن الجن مكنش فيهم رُسل ولا أنبياء، \nلكن كان فيهم نُذُر\nيعني واحد منهم يسمع عن إنذار الله للبشر عن طريق الرسل فيروح يُنذر قومه ويقول لهم إللي سمعه من الرسل مثلا،\n\"وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ .\"\n ومن أدلة جمهور العلماء قوله تعالى :\n\"وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِمْ\"\nأما الآية إللي بتقول :\n\"يا مَعْشَرَ الْجِنِّ وَالإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا \"\nفمش معناها إن الجن كان عندهم رسل من جنسهم، هو يقصد المجموع مش الجميع، يعني مجموعهم مع بعض،\nالإنس والجن ،لما ربنا بيقول: \"ألم يأتكم رسل منكم\"، يعني من أحد الجنسين،\nإللي هم الإنس، لأن الجن بيشوفوا الإنس وبيسمعوهم زي ما حصل مع رسول الله ﷺ، \nبعكس البشر مش بيشوفوا الجن، حتى السبعة من الجن دول لما رجعوا لقومهم عشان ينذرونهم،\nقالوا لهم إن في كتاب جديد أنزل من بعد موسى ، يعني هم كانوا عارفين الأنبياء والرسل من قبل كده\n\"قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ \"\nفالرسل من البشر فقط\nفلما النفر من الجن رجعوا لقومهم قالوا لهم إن في كتاب أُنزل من بعد موسى يهدي إلى الحق،\nوالمطلوب منكم إنكم تسمعوا للرسول ده وتؤمنوا به وبكلامه،\nعشان ربنا يغفر لكم ذنوبكم وينجكيكم من العذاب\n\"قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ \"\n☆سؤال\nهمّ الجن ليه قالوا لقومهم أُنزل من بعد موسى ومقلوش عيسى \nالموضوع فيه أقوال كثيرة وملغبطة، فأنا هقول لكم الراجح وإللي ذكره ابن كثير وشيخ الإسلام ابن تيمية\nقالوا:\nلأن الإنجيل تابع للتوراة، يعني التوارة التي أُنزلت على موسى هي الأصل،\nوالإنجيل جاء بيُحلل بعض الأمور التي حُرمت على بني إسرائيل في التوراة ،وهو فيه مجموعة من المواعظ ،\nوربنا قال عن عيسى عليه السلام:\n\"وَيُعَلِّمُهُ الْكِتَابَ وَالْحِكْمَةَ وَالتَّوْرَاةَ وَالإِنْجِيلَ \"\nفلو عيسى عليه السلام مكنش تبع لموسى عليه السلام في شريعته مكنش ربنا علمه التوراة \nهو ربنا علم رسول الله ﷺ التوراة والإنجيل \n؟\nلأ...لأن شريعة الإسلام مختلفة وشاملة لكل الشرائع \nفالإنجيل زي المتمم كده للتوراة يعني نقدر نقول إنه الجزء الثاني من التوراة \nعشان كده الجن قالوا موسى ومقلوش عيسى\nبدأ نفر الجن يشرحوا لقومهم هم سمعوا إيه بالضبط :\nقالوا لقومهم إنهم سمعوا قرآن عجيب في فصاحته ومعانيه الكثيرة \n\"فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا\"\nوالقرآن ده بيدعوا للحق والهدى والإيمان فعلى طول صدقناه ومش هنرجع للشرك إللي احنا كنا عليه تاني أبدا\n\"يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا\"\nوربنا العظيم جل جلاله مكنش له زوجة ولا ولد زي ماكان  سفيهنا إبليس وإللي زيه بيقولوا \n\"وَأَنَّهُ تَعَالَى جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَدًا \"\nواحنا عمرنا ما تخيلنا إن ممكن حد من الإنس ولا الجن يكذب في إن ربنا له زوجة وولد\n\"وَأَنَّا ظَنَنَّا أَنْ لَنْ تَقُولَ الْإِنْسُ وَالْجِنُّ عَلَى اللَّهِ كَذِبًا \"\nفلما سمعنا القرآن عرفنا إنهم كانوا كاذبين، فآمنا\nفي نفس الوقت إللي كان الجن بيدعوا قومهم كان رسول الله ﷺ قرب من مكة عشان يدخلها،\nلكن قبل ما نتكلم عن دخوله ﷺ  مكة، هنكمل قصة الجن لأن لها تكملة هتحصل بعد ما رسول الله ﷺ يدخل مكة ويقعد فيها كم شهر\nبعد ما النفر من الجن دعوا قومهم قالوا لازم نروح نقابل النبي ده،\nوخرجوا فعلا راحوا يقابلوا رسول الله ﷺ ، \nفي الوقت ده كان رسول الله ﷺ مع الصحابة وبعدين لقوا رسول الله ﷺ اختفى،\nدوروا عليه في الأودية والطرق مش لاقيينه فخافوا جدا إنه يكون حد قتله أو عمل فيه حاجة \nماهي الأجواء في مكة ساعتها كانت مكهربة وده إللي كان ناقص مكة تعمله مع رسول الله ﷺ\nفالصحابة قالوا: فبِتنا في شر ليلة \nمش عارفين يعملوا إيه ولا فين رسول الله ﷺ،  القلق كان هيموتهم \nفلما جاء الصبح لقوا رسول الله ﷺ راجع من ناحية طريق غار حراء،\nفأقبل عليه عبد الله بن مسعود وسأله كنت  فين يا رسول الله، احنا دورنا عليك في كل مكان \nفقال له جاءني داعي الجن عشان أروح أقرأ عليهم القرآن، فروحت قرأت عليهم القرآن، وآمن الجن،\nإللي جاءوا يسمعوا من رسول الله ﷺ، وفي روايات بتقول إنهم كانوا اثنا عشر ألف\nفتخيلوا الأعداد دي من الجن تدخل في الإسلام\nورسول الله ﷺ هو رسول للإنس والجن، يجب عليهم إنهم يؤمنوا به ويتبعوه ومن يؤمن برسول الله ﷺ يدخل الجنة ومن لا يؤمن برسول الله ﷺ يدخل النار\nواحنا حوالينا جن لما تقرأوا القرآن علّوا صوتكم شوية لعل أحد من الجن يسمعكم فيسلم ويكون في ميزان حسناتكم يوم القيامة \nأنا قلت في قصة الجن المختصر المفيد، عشان نبقى فاهمين  الدنيا ماشية إزاي ،وإلا فهي فيها روايات كثيرة وشروح كثيرة \nفاحنا نأخذ إللي يفيدنا منها عشان نبقى فاهمين القرآن\nإن شاء الله المرة الجاية هنتكلم المرة الجاية عن إزاي رسول الله ﷺ دخل مكة وإيه الأحداث إللي حصلت بعد كده \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثلاثون\n#هم_الدعوة\n#الإعداد_للرحلة\nاتكلمنا المرة إللي فاتت عن النفر من الجن الذين أسلموا بعد ما سمعوا رسول الله ﷺ  يقرأ القرآن وهو قائم يصلي   ورجعوا يدعوا قومهم للدخول في الإسلام،\nرسول الله ﷺ مكنش يعرف إن في جن سمعوه ولا أي حاجة خالص عن القصة دي لحد ما نزل القرآن وأخبر رسول الله ﷺ بقصة الجن،\nوإسلام المجموعة دي من الجن كانت من بشارات استجابة دعاء رسول الله ﷺ \nربنا أراد إنه يهوّن على قلب رسول الله ﷺ بعد موت أبي طالب وموت خديجة والأذى إللي تعرض له في الطائف،\nفكانت أولها ترقيق قلب اثنين من المشركين من أشد أعداء رسول الله ﷺ وإرسالهم للطعام مع عدّاس العبد النصراني،\nوإسلام عداس وكانت دي ثاني البشريات،\nوبعد كده إرسال ملك الجبال، وبعدين إسلام الجن \nفمهما كانت الأحداث مؤلمة والابتلاءات شديدة هتلاقي ربنا بيلطف بالإنسان\n☆عارفين،\nفي نوعين من اللُّطف: \nلُطف ظاهر ولُطف باطن،\nاللطف الظاهر إن ربنا يبعد عنك الأذى، مثلا واحد كان هيقع من على السلم ومسك نفسه، \nكانت هتخبطك عربية فبعدت عن الطريق قبل ما تحصلك الحادثة وهكذا وده بيحصل كثير وبنشوفه،\nوحتى تلاقينا كثير بنقول الحمد لله ده ربنا لطف بينا ...ده كان ممكن تحصل كارثة \nأما بقى اللطف الباطن فمعناه إن ربنا بيجعل في القلب سكينة واطمئنان كده ورضا، ومفيش قلق واضطراب مهما حصل لنا من المصائب والابتلاءات،\nيعني في موقف رسول الله ﷺ قلبه كان فيه رضا واطمئنان وسكينة، ومش معنى إنه بكى وتألم فقلبه مفهوش رضا\nلأ ..ده رسول الله ﷺ \nواحنا اتكلمنا عن الفرق بين الرضا والصبر وإنهم لا يتعارضوا مع الحزن والألم في قصة يعقوب لما فقد ابنه يوسف عليهما السلام \nفمع وجود الرضا والإطمئنان بيكون في مسحة حزن كده في القلب ودي حاجة طبيعية في النفس البشرية\nيعني مهما كان القلب فيه سكينة ورضا واطمئنان فبيكون في القلب عَضة حزن وألم،\nيعني لما رسول الله ﷺ بكى وتألم ده كان بسبب عضة الحزن في قلبه ﷺ،\nولأن رسول الله ﷺ قدوة فكان لازم يمر بالألم ده عشان\nلما تلاقي في قلبك عضة الألم والحزن دي مع إنك راضي بقضاء الله وقلبك فيه سكينة متستغربش، \nربنا يقول لنا إن دي طبيعة النفس البشرية... قدوتكم إللي أمرتكم تتبعوه حصل معاه كده\nفكان من لطف ربنا برسول الله ﷺ إنه يرسل له البُشريات عشان يخفف عن قلبه عضة الحزن إللي كان حاسس بها دي،\nوربنا هيعمل حاجة لرسول الله ﷺ يمحوا بها عضة الحزن دي من قلبه تماااما هنعرفها إن شاء الله لما ييجي وقتها \nنرجع لرسول الله ﷺ إللي المفروض واقف خارج مكة  ومحتاج إنه يدخلها، لكن في مشكلة دلوقتي\nهيدخل إزاي وظاهر الأوضاع إن دخول مكة في الوقت ده صعب،\nواحتمال كبير يغدروا بيه ويقتلوه\nماهو في وجهة نظرهم خائن لأنه خرج عليهم وراح يطلب النصر من قبائل تانية \nوهو ملوش أحد يحميه في مكة، كبير بني هاشم أبو طالب مات....أبو لهب من أشد أعداء الإسلام\nوحتى لو مفيش خطورة على حياته،\n لو رسول الله ﷺ  دخل مكة كده عادي بعد ما طُرد من الطائف، المشركين هيشمتوا فيه وفي المسلمين وهيصوروا الموضوع إنه هزيمة لرسول الله ﷺ  وللمسلمين ، وربنا يكفيكم شر شماتة الأعداء\nرسول الله ﷺ  فكر إزاي يدخل مكة ويحافظ على حياته وفي نفس الوقت لا يعطي الفرصة للمشركين إنه يشمتوا فيه ،\nكان الحل إنه يستغل قانون من قوانين الجاهلية لصالحه وهو قانون الإِجارة، يعني الحماية،\nوهو إن الرجل إللي ملوش أحد يحميه ،يدخل تحت حماية رجل له قوة ومنعة في القبيلة،\nوطبعا مادام القانون مفهوش أي تعارض أو تنازل عن أي حاجة في الدين يبقى عادي جدا إننا نعمل به أو المسلم يستغله لمصلحته زي ما رسول الله ﷺ  عمل،\nيعني الإسلام مش بيحارب القوانين لذاتها، هو بيحارب القوانين إللي تتعارض مع تشريعات ربنا فقط\nفقرر رسول الله ﷺ إنه يدخل في جوار أو في حماية واحد من سادات مكة المشركين \n☆ليه\nلأن لو رسول الله ﷺ دخل في حماية واحد من المسلمين هيبقى كأنه بيعلن الحرب على مكة وهنا هتنقسم مكة لفريق مؤمن وفريق كافر،\nورسول الله ﷺ  مش عايز كده دلوقتي لأن مش هو ده الوقت المناسب للمواجهة،\nالمسلمين لسه مستضعفين، عايزين نحط قواعد ثابتة عشان لما تحصل المواجهة لا يُباد المسلمين ويرجع وضعهم أسوأ من الأول \nومع إن عدّى عشر سنين لحد دلوقتي من بداية الدعوة للإسلام، إلا أن المسلمين لسه مستضعفين ، \nوإللي بيدعو مين...ده رسول الله ﷺ  أفضل من مَشى على الأرض، سيد الأولين والآخرين ، المُؤيد بالمعجزات ولسه المسلمين مستضعفين،\nواخدين بالكم من الرسالة إللي ربنا يريد إنه يوصلها لنا\nربنا بيقول لنا متستعجلوش على النتائج...اصبروا...إللي أحسن منكم بمراحل قعد عشر سنين يدعو ولسه المسلمين مستضعفين،  \nفما بالكم باللي أقل منه محتاج أد إيه \nوعشر سنين زمن مش قليل على فكرة،\n ومع ذلك رسول الله ﷺ  كان بيتصرف بحكمة مش بتهور زي ما بعض المسلمين بيعملوا ومستعجلين النتائج فيضيعوا تعب سنين في الدعوة بسبب موقف واحد متهور\nرسول الله ﷺ  عارف إن سنين طويلة من الضياع والبعد عن الدين وتغلغل الكفر والظلم في قلوب الناس مش هيتغير بثورة ولا هيتغير بمواجهة متهورة مش محسوب لها أي حساب،\nرسول الله ﷺ معندوش مانع إنه يعلم الناس ويأصل العقيدة في قلوبهم، ويربيهم صح حتى لو استمر الأمر سنين طويلة عشان لما تحصل المواجهة الحقيقية تكون النتيجة هي انتصار الدين\nلو اتبعنا منهج رسول الله ﷺ  زي ما ربنا أمرنا أوضاعنا كلها هتختلف، \nلكن للأسف كل واحد بيفكر بدماغه من غير ما يرجع لمنهجه ﷺ \nأو ممكن بيرجع للمنهج بس بياخد مواقف من حياة رسول الله ﷺ ويحطها في غير مكانها،\nتلاقي إللي يقول رسول الله ﷺ  قاتل الكفار إللي ظلموا المسلمين، \nفاحنا كمان هنقاتلهم\nهو الكلام صحيح ، رسول الله ﷺ  قاتل المشركين، بس قاتلهم إمتى؟ \nلما المسلمين كانوا مستضعفين والباطل قوته أقوى من قوة الحق بمراحل ؟\nولّا قاتلهم بعد أربعة عشرة عام من بداية الدعوة وتعليم المسلمين العقيدة الصحيحة، والتعرض للابتلاءات والأذى والقتل \nعشان نأخذ قرار من حياة رسول الله ﷺ  ونطبقه في حياتنا لازم نشوف الظروف المحيطة بالقرار ده كان عامل إزاي،\nوهل ظروفنا احنا كمان مشابهة للظروف بتاعة القرار ده ولّا لأ\nفاكرين لما اتكلمنا عن مقتل ياسر وزوجته سمية، \nرسول الله ﷺ عمل إيه \nكان بيعدّي عليهم وهم بيعذبوا ويقول لهم صبرا فإن موعدكم الجنة،\nولما قُتلا.. لم يقتل رسول الله ﷺ أبا جهل إللي قتلهم أو يأمر بقتله ، مع إنه يستحق القتل قصاصا \nلكن بعدين زي ما هنشوف ، في مسلم واحد هيُقتل ، \nرسول الله ﷺ  مسكتش...ده جهز جيش عشان يروح ويثأر للي قتل المسلم ده،\nإيه الفرق بين الموقفين...هل المسلم ده أفضل من المسلم ده؟\nلأ..لكن الظروف هي إللي اختلفت...عشان كده لازم نتعلم إننا مناخدش أي قرار إلا لما ندرس الواقع بتاعنا والظروف كويس أوي زي ما رسول الله ﷺ  كان بيعمل \nرسول الله ﷺ أرسل للمُطعم بن عدي المشرك عشان يكون في جواره،\nوالمطعم بن عدي فاكرينه\nكان واحد من الخمسة إللي كان عنده مروءة واشترك في نقض صحيفة شعب أبي طالب \nفلما عرف إن رسول الله ﷺ عايز يدخل في جواره وافق ونادى على أبنائه وقومه وقال لهم إلبسوا السلاح بتاعكم وتعالوا معايا عشان أنا اجرت محمد،\nووقفوا عند باب مكة مستنيين رسول الله ﷺ  يدخل عشان يحموه، \n☆من عجائب العرب إن مفيش حد من القبيلة بيرد على سيدهم ويقول له واحنا مالنا،\nإنت أَجرته خلاص روح احميه مع نفسك، إزاي تورطنا في حاجة زي كده من غير ما تسألنا \nعارفين إللي كان ممكن يقول الكلام ده مين \nبني إسرائيل \nإللي خلاهم يقولوا لموسى عليه السلام روح إنت وربك فقاتلا واحنا هنقعد هنا نستناكم، عادي يقولوا الكلام ده \nلكن العرب أيام رسول الله ﷺ غيييير ، كانوا بيحترموا جدا الكلمة،\nمجرد ما أحد يقول أنا أجرت فلان خلاص كلهم على قلب رجل واحد يحموا الشخص ده، ويدافعوا عنه بحياتهم\nدخل رسول الله ﷺ مكة مرفوع الرأس ، وتوجه ناحية الكعبة ومعاه المطعم بن عدي وأبنائه وأفراد قبيلته ماشيين حواليه بالسلاح بيحموه، \nوصلوا لحد الكعبة ، وأول ما وصلوا وقف المطعم وسط الناس وقال :\nيا معشر قريش!\nمحمد في حمايتي محدش يقرب منه ولا يؤذيه حتى بكلمة \nصلى رسول الله ﷺ  عند الكعبة ركعتين في حماية المطعم بن عدي،\nوفي هنا رسالة خفية من رسول الله ﷺ  لأهل مكة بما فيهم المطعم بن عدي\nبيقول لهم بطريقة عملية أنا لسه على طريقي، أنا لسه متمسك بدعوتي، ومش معنى إني دخلت في جوار المطعم بن عدي المشرك إني هسكت وهتنازل عن الدين،\nلأ..كل حاجة هتمشي زي مانا عايز...ومفيش أي تنازل عن أي شيء في الدين\nودي رسالة لنا احنا كمان، رسول الله يقول لنا نستعمل أي قانون ممكن يحقق لنا مصلحة، مادام مفيش في المقابل أي تنازل في الدين،\nولو كان المطعم بن عدي قال لرسول الله ﷺ إنه يحميه بشرط إنه يتوقف عن الدعوة مكتش رسول الله ﷺ  هيوافق أبدا\nرجع رسول الله ﷺ لبيته وسط الحماية دي ووقف حراس على بيته من الخارج يحرسوه،\nوالأوضاع هدأت في مكة نسبيا، بعد الإجارة دي\nعايزاكم تتخيلوا لما رسول الله ﷺ  يدخل بيته بعد الأحداث دي كلها، أحداث الطائف والجن ودخوله لمكة، \nوميلاقيش إللي كانت بتستقبله لما يرجع ،وتسمعه لما يحكيلها ويفضفض معاها،\nهيحكي لمين دلوقتي...رسول الله ﷺ  بشر يعني من الإنس يعني بيأنس بالبشر هو كمان... زيه زينا،\nفانتم متخيلين إحساسه كان عامل إزاي ساعتها، متخيلين عضة الحزن في قلبه كانت إزاي\nمين إللي عالم بالحزن ده ...اللطيف الخبير \nماهو كل إللي حصل ده كله كان بتقدير ربنا، ولو شاء ربنا محدش كان يقدر يمس رسول الله ﷺ بأي شيء، ولو شاء الله مكنش قبض روح خديجة،\nيعني كل ده ابتلاء من الله عز وجل، وربنا الرحيم اللطيف الودود لما يبتلي الإنسان ميسبوش،\nبيبعث له حاجات تخفف عنه، زي ما شفنا موقف عداس والجن\nواحنا برده لو كل واحد تأمل في حياته هنلاقي مع الإبتلاء ربنا بيلطف بينا ويبعث لنا حاجات تخفف عننا،\nزي ما الناس بتقول 《ربنا بيطبطب علينا》 والكلمة دي لا تجوز بالمناسبة \nلأن احنا مينفعش نوصف ربنا بحاجة هو لم يصف نفسه بها،\nيبقى مينفعش نقول ربنا بيطبطب علينا ،لكن نقول ربنا بيلطف بينا \nربنا بقى أراد إنه يُزيل الحزن إللي في قلب رسول الله ﷺ ده من جذوره ويفرحه\nفي الوقت إللي كان بيترتب لرسول الله ﷺ خطة تفرحه كان رسول الله ﷺ  بيفكر في الوضع بتاعه ،\nوإزاي يبدأ يتحرك بالدعوة عشان ينشرها برة مكة، برغم الظروف المؤلمة إللي هو فيها، \n☆ودي رسالة بتقول لنا ...مفيش حاجة اسمها أصل أنا ظروفي صعبة ، محدش ظروفه أصعب من ظروف رسول الله ﷺ، \nربنا كان قادر إنه ينصر رسوله من أول يوم ولا إنه يعرضه للأذى ده،\nبس عشان يقول لنا إن الطريق مش سهل، ومع ذلك لازم تكمل زي رسول الله ﷺ  ما كمل\nخلونا نفكر مع رسول الله ﷺ ،\nهو دلوقتي في حماية المطعم بن عدي، لكن موقف المطعم بن عدي موقف مؤقت، \nلو قريش صبرت سنة سنتين على الوضع ده ،مش هتقدر تصبر مدة طويلة ، \nوحتى المطعم بن عدي نفسه له طاقة ومش هيقدر يحمي رسول الله ﷺ على طول،\nوممكن بسبب ضغط من قريش المطعم يترك حماية رسول الله ﷺ وساعتها هتبقى مشكلة،\nيبقى الحل دلوقتي إيه\nإننا نشوف وضع دائم يحميه ويحمي الدعوة بدل الوضع المؤقت مع المطعم بن عدي،\nيبقى محتاجين نبحث عن ناس لهم مكانة برة مكة، أقوياء يؤمنوا ويقدروا ينصروا رسول الله ﷺ  ودعوة الإسلام ،\nيبقى هو ده القرار الصحيح، البحث عن من ينصر الدعوة\nرسول الله ﷺ همه الدعوة وهمه الإسلام وهمه الآخرة،\nوإللي بيكون ده همه،\nربنا بيخليه يشوف المعجزات أو الكرامات إللي تفرح قلبه مهما كان عايش في ابتلاءات\nنشوف ربنا جهز إيه لرسول الله ﷺ عشان ينزع من قلبه عضة الألم \nكان رسول الله ﷺ في بيته وفجأة سقف بيته اتفتح ، ونزل منه جبريل عليه السلام،\nوكان جبريل عليه السلام يأتي لرسول الله ﷺ في صورة بشر،\nلما نزل جبريل على رسول الله ﷺ في بيته، شق صدره\nودي المرة الثانية إللي يُشق فيها صدر رسول الله ﷺ، \nالمرة الأولى لما كان صغير واتكلمنا عنها في البداية\nفجبريل شق صدر رسول الله ﷺ بدون بنج وبدون دم يسيل وبدون ألم ولا أي حاجة خالص\nفلما شقه فتح اللحم وطلع قلبه ﷺ وغسل جبريل صدر رسول الله ﷺ  من الداخل بماء زمزم، \nوغسل قلبه كمان بماء زمزم لحد ما جوف رسول الله ﷺ بقى نقي \nوبعدين جاء جبريل عليه السلام بطِست من ذهب يعني طبق كبير من ذهب مليان حكمة وإيمان،\nفأفرغها في صدره ﷺ،\nوقفل اللحم على بعضه ومسح جبريل على اللحم فرجع زي مكان ولا كأن كان في صدر مفتوح ولا أي حاجة \nطبعا في هنا أسئلة كثيرة وفين وإزاي ومعقول و...و....الكلام ده حصل ورسول الله ﷺ  حكاه والحديث في البخاري،\nوإللي بيؤمن بالله مش هيلاقي صعوبة إنه يصدق الكلام ده\nإللي حصل مع رسول الله ﷺ ده اسمه معجزة،\nوالمعجزة هي الشيء الخارق للعادة، يعني برة قوانين العقل أصلا \nفطبيعي إن العقل ميستوعبش الكلام ده، وهنا ييجي دور الإيمان بالغيب وبقدرة الله \nهو ربنا رافع السماوات بغير عمد ، خالق الكون، خالق البشر أصلا وخالق كل ذرة في الكون مش هيقدر يقول للدم لا تنزف ، مش هيقدر يوقف الإحساس بالألم،\nالله على كل شيء قدير\nيبقى نقول آمنا بك يارب وبقدرتك وآمنا بكل الغيب \nربنا بيجهز رسول الله ﷺ لرحلة، لكن الرحلة دي مش زي أي رحلة، عشان كده التجهيزات بتاعتها كانت تجهيزات خاصة جدا ،\nبيجهزه لرحلة الإسراء والمعراج\nإيه الرحلة دي وإيه إللي حصل فيها ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 57, "l": "الجزء 31 | رحلة الإسراء والمعراج | الإسراء", "u": "https://www.facebook.com/groups/710210019782034/permalink/780837882719247/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الحادية_والثلاثون\n#رحلة_الإسراء_والمعراج\n#الإسراء\nكنا واقفين المرة إللي فاتت عند جبريل عليه السلام لما جاء لرسول الله ﷺ وغسل صدره وقلبه عشان يجهزه لرحلة الإسراء والمعراج،\nقبل ما ندخل في التفاصيل أحب أوضح كم نقطة\n◇كل المعلومات إللي هقولها عن الإسراء والمعراج مصدرها الأحاديث الصحيحة فقط، متجمعة جنب بعض عشان تكون القصة،\nطبعا ده مش اجتهادي\n أنا بسمع من المشايخ والعلماء الموثوق في علمهم وبدور على الأسئلة والشُّبه وإجابتها وبشرح بأسلوبي مش أكثر\n◇الإسراء والمعراج حصل بعد رجوع رسول الله ﷺ من الطائف، لكن في أي شهر أو في أي يوم محدش يعرف نهائي\nلا في حديث صحيح ولا حديث ضعيف ولا حتى حديث موضوع إن ليلة الإسراء والمعراج كانت في ليلة السابع والعشرين من رجب،\nوبالتالي الليلة دي ملهاش أي فضل لا بصلاة ولا بذكر ولا بقيام ولا بصيام ولا احتفال ولا أي حاجة خالص،\nيوم زيه زي أي يوم تاني \n◇الهدف من الرحلة دي إن ربنا يهون على رسول الله ﷺ  الابتلاءات إللي حصلت معاه وإللي هتحصل بعدين، ليثبت قلبه عشان يقدر يكمل في طريق نشر الدعوة\n◇رحلة الإسراء والمعراج كانت بالروح والجسد، مش بالروح فقط ولا هي تهيؤات ولا حلم ولا أي حاجة خالص\nجبريل جاء لرسول الله ﷺ وهو صاحي زينا كده عادي وأخذه في رحلة الإسراء والمعراج\nوالدليل إن ربنا قال:\n\"سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ \"\nوالعبد يتكون من روح وجسد \n◇رحلة الإسراء والمعراج معجزة حصلت لرسول الله ﷺ واحنا كمسلمين بنؤمن بها، وهي من الغيب، ومن صفات المؤمنين إنهم بيؤمنوا بالغيب،\nوإللي مش مقتنع ومش عايز يؤمن بها هو حر ..مع نفسه ويبقى يقول كده لربنا يوم القيامة\n\"وَقُلِ الْحَقُّ مِنْ رَبِّكُمْ فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ \"\nنبتدي الرحلة مع رسول الله ﷺ من البيت الحرام لحد ما نوصل للمسجد الاقصى،\nنشوف رسول الله ﷺ  هيروح هناك إزاي\nخرج رسول الله ﷺ مع جبريل خارج بيته فوجد دابة، حيوان أبيض طويل، أكبر من الحمار وأصغر من البغل،\nعليه السّرج واللّجام، إللي هو القعدة إللي بتتحط على الحصان دي عارفينها \nومفيش دليل على إن الحيوان ده كان له أجنحة \nوكان اسم الحيوان ده 《البُرَاق》، ركب عليه رسول الله ﷺ مع جبريل عليه السلام،\nوكانت خطوة البراق مد بصره، يعني مطرح ما عينه تجيب يحط رجله ،فتخيلوا سرعته أد إيه\nعشان كده اسمه البراق، لأن سرعته زي سرعة البرق كده\n☆وليه رسول الله ﷺ  ركب أصلا على البراق، مش ربنا قادر إنه يوصله للمسجد الأقصى بدون ما يركب حاجة\nركوب البراق كان زيادة في تشريف رسول الله ﷺ ، لأنه لو راح بنفسه كده كان هيبقى في صورة الماشي،\nوالراكب أعز من الماشي \nانطلق البراق بسرعته لحد ما وصلوا عند قبر موسى عليه السلام نفسه بقى\nوقبر موسى عليه السلام قريب جدا من الأرض المقدسة أرض فلسطين على مسافة رمية حجر ،\nواحنا اتكلمنا في الجزء الرابع والثلاثون من قصص الأنبياء عن موت موسى عليه السلام لو حابين ترجعوا له،\nفمش هعيد الكلام هنا تاني،\nعدّى رسول الله ﷺ على موسى عليه السلام وهو قائم يصلي في قبره،\n☆الأنبياء لهم وضع مختلف، فربنا حرم الأرض إنها تأكل أجسادهم، يعني أجسادهم لا تتحلل زي باقي البشر،\n فكل الأنبياء في قبورهم دلوقتي كأنهم نايمين بالضبط \nوهم يتميزوا عن باقي البشر إن ربنا بيحييهم حياة خاصة بعد الموت،\nبعكس باقي البشر إللي بعد ما يجاوبوا على أسئلة منكر ونكير، يُفتح لهم باب من الجنة أو باب من النار، ويُنعم من يُنعم ويُعذب من يُعذب،\nوصلاة الأنبياء في القبر مش صلاة تكليف زي صلاتنا في الدنيا، إنها واجبة عليهم يعني\nتقدروا تقولوا إنها صلاة حب، يعني عبادتهم في القبر عبادة تشريف ربنا ألهمهم بها،\nزي مثلا أهل الجنة ربنا يُلهمهم التسبيح زي ما ربنا بيُلهمنا إننا نتنفس،\nمش التنفس عندنا حاجة طبيعية، كذلك تسبيح أهل الجنة حاجة طبيعية وصلاة الأنبياء في قبورهم حاجة طبيعية\nفموسى عليه السلام كان بيصلي في قبره ورسول الله ﷺ رآه لأن ربنا أعطى له القدرة على رؤية الأمور الخارقة دي،\nلما حصل التجهيز قبل الرحلة،\nلما جبريل عليه السلام رجع قلب رسول الله ﷺ  مكانه ومسح على صدره وقال له:\nفيه أذنان سميعتان وعينان بصيرتان ، لسانك صادق ونفسك مطمئنة!\nعشان كده رسول الله ﷺ  كان بيشوف ويسمع إللي غيره مكنش يشوفه ولا يسمعه \nومنها إنه رأى موسى عليه السلام وهو يصلي في قبره\nانطلق رسول الله ﷺ مع جبريل على البراق لحد ما وصلوا بيت المقدس، عند المسجد الأقصى، فنزلوا من على البراق وخرق جبريل عليه السلام الصخرة بإصبعه وربط فيه البراق،\n☆هو البراق هيتسرق يعني ..خرم الصخرة وربط فيه البراق ليه\nبكل بساطة عشان يعلمنا الأخذ بالأسباب \nمش احنا متفقين إن كل حاجة في حياة الأنبياء بصفة عامة وحياة رسول الله ﷺ بصفة خاصة ربنا بيوصلها لنا عشان فيها عبرة وفائدة\nأهه العبرة من الموقف ده إننا نأخذ بالأسباب\nبعد ما ربط البراق دخل مع جبريل عليه السلام للمسجد الأقصى،\nوكان الأنبياء كلهم موجودين في المسجد الأقصى منتظرين رسول الله ﷺ  عشان يصلي بهم\nالأنبياء كلهم يعني المائة وأربعة وعشرون ألف نبي ورسول \nتخيلوا إحساس رسول الله ﷺ لما دخل المسجد ولقى كل الأنبياء دول\nوقال له جبريل تقدم وصلي، وفعلا رسول الله ﷺ تقدم وصلى ولما خلص صلاة لقى الأنبياء صلوا وراه\nيعني هو كان إمام للأنبياء والرسل،\nآدم وإبراهيم وإدريس ونوح وإبراهيم ويونس وعيسى وهارون وموسى وشعيب أيوب وزكريا ويحيي ولوط و...و...\nمتصورين المشهد\nالموقف ده دليل واضح ورسالة من ربنا إن يا محمد أنت أفضل من جميع الأنبياء،\nأنت أشرف من مشى على الأرض\nرسول الله ﷺ إللي كان حزين على موت زوجته وعمه ، وحزين من الأذى إللي هو تعرض له،\nتعتقدوا هو فاكر منه حاجة دلوقتي \nيعني واحنا بنحكي نسينا أصلا إن رسول الله ﷺ مر عليه الألم ده ، فما بالكم به هو \nبس لسه برده ، ربنا الكريم لما يريد إنه يُفرح عبده بيفرحه باللي مكنش يخطر على باله أبدا \nبعد ما رسول الله ﷺ خلص صلاة جاءه جبريل بكأسين ، كأس فيه لبن وكأس فيه خمر، وقال لرسول الله ﷺ  اختار واحد فيهم واشرب، وساعتها كانت الخمر حلال،\nفاختار رسول الله ﷺ  اللبن ، فقال له جبريل هُديت وهُدِيَت أمتك!\n\"سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا ۚ إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ\"\n☆طبعا السؤال إللي ييجي في بالنا دلوقتي هم الأنبياء صلوا إزاي وهم ميتين \nالقول الراجح في الموضوع إن ربنا جعل أرواح الانبياء تتشكل في صورة الأجساد الحقيقية،\nيعني أجساد الأنبياء في المقابر عادي لكن أرواحهم في الجنة ما عدا عيسى عليه السلام ، فهو روحه وجسده في السماء زي ما قلنا في قصته قبل كده\nفلما رسول الله ﷺ  جاء للمسجد الأقصى جاءت الأرواح وتشكلت في صورة الأنبياء وصلوا جميعا خلف رسول الله ﷺ ولما خلصوا صلاة رجعوا للسماء مرة ثانية،\nواحنا قلنا الانبياء حياتهم البرزخية إللي بعد الموت تختلف عن باقي البشر \n◇ممكن حد يسأل ويقول لما الأنبياء أرواحهم في الجنة إزاي موسى عليه السلام كان بيصلي في قبره \nالأرواح من جنس أمر الملائكة، يعني بتطلع وتنزل وتروح وتيجي في لحظة\nمش بنبقى نايمين ونحلم إننا طلعنا مكان عالي وننزل في لحظة،\nأو نكون في مكان وفجأة المشهد يتغير لمكان تاني خالص أهه دي الروح إللي بتروح وتيجي كده \nفأرواح الأنبياء في الجنة ولها اتصال بالجسد في الأرض، \nإزاي وبأَيّ طريقة... الله أعلم\nدي من الأمور الغيبية إللي منعرفش عنها حاجة،\nلأن حياة البرزخ مختلفة تماما عن الحياة الدنيا، فيجب إننا نؤمن بها وخلاص زي ماهي من غير ما ندخل في تفاصيل \nأقول لكم مثال يقرب المعنى شوية \n شوفوا الشمس كده مكانها فين؟ \nمكانها في المجموعة الشمسية بعيد عن الأرض ، ومع ذلك الشمس بتدفئ الأرض ولها أثر كبير على الأرض،\nنفس الموضوع مع الروح \nبعد ما رسول الله ﷺ شرب اللبن المفروض إنه يرجع خلاص،\nلكن لأ...لسه في رحلة تانية خااالص، مختلفة عن كل حاجة ممكن أي بشر يتصورها\nرحلة الثانية هي رحلة المعراج، يعني رسول الله ﷺ هيطلع للسماء\nهيطلع إزاي وهيشوف إيه وهيقابل مين ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡\n◇◇ملحوظة مهمة:\nأنا كنت قبل كده قلت حديث إن رسول الله ﷺ صلى عند جبل الطور في المكان إللي ربنا كلم فيه موسى، وصلى ببيت لحم وصلى بطيبة،\nلكن بعد البحث الحديث طلع غير صحيح عشان كده أنا عدلت الجزء ده وشيلت الحديث وشرحه."}, {"n": 58, "l": "الجزء 32 | الإسراء والمعراج | المعراج الجزء الأول", "u": "https://www.facebook.com/groups/710210019782034/permalink/780864342716601/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والثلاثون\n#رحلة_الإسراء_والمعراج \n#المعراج_الجزء_الأول\nوقفنا المرة إللي فاتت عند جبريل عليه السلام لما أعطى رسول الله ﷺ  كأسين واحد فيه لبن والثاني فيه خمر،\nفشرب رسول الله ﷺ  من الكأس إللي كان فيه لبن فقال له جبريل عليه السلام: هُديت وهُديت أمتك،\nوالمتوقع إن رسول الله ﷺ  يرجع بقى لمكة لكن كان في رحلة ثانية مستنياهﷺ \nرحلة مختلفة عن أي رحلة ، رحلة المعراج..يعني الصعود للسماء، \nهنبدأ بإزاي رسول الله ﷺ  طلع للسماء رسول الله بيحكي وبيقول إنه طلع على حاجة زي السلم كده،\n ولكن السلم ده مختلف، فهو مكون من ثلاث درجات، يعني يطلع الدرجة الأولى وبعدين الثانية وبعدين الثالثة وبعد الثالثة يوصل للسماء،\n فكل سماء هيوصل لها هتكون بالطريقة دي، درجة اثنين ثلاثة وبعدين السماء وهكذا،\nفصعد رسول الله ص مع جبريل على السلم الثلاث دراجات وبقى على باب من أبواب السماء الدنيا، \nوالسماء الدنيا إللي هي السماء الحقيقية مش الجزء الظاهر إللي احنا شايفينه ده \nحتى رسول الله ﷺ  بيقول إنه لو أراد إنه يلمس السماء للمسها، \nيعني يقدر يحط إيده عليها ويحسس عليها ويحس بها زي ما بنحط إيدنا كده على الحائط مثلا \nوطبعا مش هنسأل هو رسول الله ﷺ  كان بيتنفس إزاي وهو في الفضاء الخارجي ومفيش أكسجين\n احنا بنتكلم عن رسول الله ﷺ  وبنتكلم عن ربنا يعني احنا برة السنن الكونية أصلا وبرة كل القوانين\n فلما وصل جبريل عليه السلام لباب من أبواب السماء الدنيا وخبط على الباب فخازن الباب ...الحارس يعني سأل : مين؟، فقال : جبريل!\n فسأله خازن هل معك أحد فقال له جبريل عليه السلام :معي محمد!\n فسأله الخازن :هو أُرسل إليه؟ يعني ربنا أمر إنه ييجي ، فجبريل عليه السلام قال : نعم !\n،فقال الخازن فلنِعم المجيء جاء وفرح به أهل السماء ،\n يعني كأن الخازن بيقول بلغتنا كده ده الدنيا نورت\n☆هنشوف أد إيه في تشابه بين نظام الحياة في السماء والأرض، \nفزي ما فيه عندنا في الأرض شركات مثلا وعليها حراس بيحرسوها وبيشوفوا إللي داخل وإللي طالع، \nبرده في السماء هنلاقي كل سماء عليها حراس من الملائكة وظيفتهم حراسة أبواب السماء \nلما دخل رسول الله ﷺ  السماء الدنيا شاف رجل قاعد في السماء حوله سواد عظيم ،لما ينظر ناحية يمينه يضحك ولما ينظر ناحية شماله يبكي، \nفرسول الله ﷺ سأل جبريل من هذا؟!\n فقال له جبريل عليه السلام : هذا أبوك آدم سلم عليه!\n فسلم رسول الله ﷺ  على أدم،  فقال آدم عليه السلام لرسول الله أهلا بابني ، أهلا بالابن الصالح والنبي الصالح فلنعم الابن أنت ،ودعا لرسول الله ﷺ  بخير،\nوبعدين مشي رسول الله مع جبريل عشان يكمل الرحلة\n☆إذا كان رسول الله ﷺ  مشفش والده، لكنه شاف أبوه الأكبر آدم عليه السلام\n.\n◇نقف كده مع بعض ثواني نجاوب على كم سؤال \n¤أولا:\n إزاي رسول الله ﷺ  يسأل جبريل عن آدم عليه السلام من هذا وهو كان لسه مصلي معاه في المسجد الأقصى من شوية\nمبدئيا هو في خلاف بين العلماء، هل رسول الله صلّى بالأنبياء قبل المعراج ولا صلى بهم بعد المعراج ، في علماء قالوا إنه صلى قبل المعراج وعلماء قالوا إنه صلى بهم بعد المعراج وكل فريق له أدلته\nفأنا شرحت لكم المرة إللي فاتت إن رسول الله ﷺ  صلى بالأنبياء قبل المعراج، وعلى الأساس ده تكون الإجابة كالتالي :\nرسول الله ﷺ  لما دخل المسجد دخل صلى على طول من غير ما يركز في وجوه الانبياء، ده غير الرهبة إللي حصلت له لما شاف الاجتماع الرهيب للأنبياء ده فأكيد مش هياخد باله  من كل المائة وأربعة وعشرين ألف نبي \nتخيلوا لما ندخل مكان زحمة بنبقى شايفين وجوه ناس كثيرة لكن مش مركزين في الأشخاص نفسهم شكلهم وملامحهم إيه\n فدلوقتي رسول الله شايف دلوقتي آدم عليه السلام وجها لوجه ، فطبيعي إنه يسأل عن الشخص إللي قصاده دلوقتي ده هو مين بالتحديد، وخصوصا لما شاف السواد إللي حواليه وشاف بكاؤه وضحكه.\nلكن لو القول الثاني بإن رسول الله ﷺ صلى بالأنبياء بعد المعراج يبقى مفيش إشكالية لأنه أول مرة كان يقابلهم كانت في السماء\n¤السؤال الثاني إيه هو السواد إللي كان حول آدم عليه السلام ده\nالسواد ده هو نسمات أو أرواح أبنائه إللي لسه لم يولدوا من أهل الجنة ومن أهل النار ،\nفلما كان ينظر على نسمات أهل الجنة ناحية اليمين كان يضحك فرحا بهم،\nولما كان ينظرعلى نسمات أهل النار ناحية الشمال كان يبكي حزنا عليهم لأنهم فشلوا في الإختبار\n وموقف البكاء ده يعتبر موقف عارض ، يعني مش إن آدم عليه السلام قاعد بس ينظر ناحية اليمين ويضحك وناحية الشمال ويبكي إلى قيام الساعة، \nلأن احنا  قلنا إن الأنبياء لهم حياة خاصة بعد الموت وإن أرواحهم موجودة في الجنة أصلا فهو خرج من الجنة عشان يقابل رسول الله ﷺ زي باقي الأنبياء إللي رسول الله ﷺ  هيقابلهم في باقي السماوات، \nووجود آدم عليه السلام في السماء الدنيا بالّذت مش في أي سماء ثانية لأن هو بيعرض عليه نسمات أهل النار ، ونسمات أهل النار مش بيعدوا السماء الدنيا ، ربنا بيقول:\n \"إِنَّ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا لا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ\"\nفتزَامن مجيء رسول الله ﷺ  مع عرض نسمات بني آدم عليه عشان يشوف الموقف ويحكيه لنا\n انطلق رسول الله مع جبريل عليه السلام فشاف في السماء الدنيا ثلاثة أنهارعظيمة ، أول نهرين شافهم كانا النيل والفرات، \nوهيشوفهم برده في السماء السابعة ولما يدخل الجنة في رحلته دي\nفالنيل والفرات أصلهما من الجنة، فهما بيخترقا السماء وبعدين ربنا بيُرسل ماء النيل لجبال أثيوبيا ووسط أفريقيا، ويرسل ماء الفرات لجبال تركيا فينزل على هيئة مطر هناك، ويتكون النهرين ويمشوا في المسار بتاعهم إللي ربنا خلقه لهما\nطبعا الكلام ده من تفسير أحاديث رسول الله، فسبحان الخالق المدبر \nالنهر الثالث إللي شافه رسول الله ص وهو ماشي كان نهر الكوثر، وهو هدية من رب العالمين ،فاكرين إنا أعطيناك  الكوثر \n☆ملاحظين إن ربنا بيخلي رسول الله ﷺ  يشوف الغيب إللي كان بيحكي للصحابة عنه\n نهر الكوثر... أدم عليه السلام.. شكل السماء ولسه إللي جاي\nخلّص رسول الله ﷺ  السماء الدنيا أو السماء الأولى وبعدين طلع للسماء الثانية بنفس الطريقة إللي قلناها في الأول،\n سلمة والثانية والثالثة وبقى على باب من أبواب السماء الثانية،\nووقف جبريل عليه السلام على الباب وخبط عليه،\n ورد عليه خازن الباب وقال : مين؟!\n فقال : جبريل! فقال له : مين معاك؟! قال جبريل عليه السلام: محمد!\n فقال الخازن: وهو ربنا أذن له إنه ييجي؟!\n فقال جبريل: نعم!.. فقال الخازن: فلنعم المجيء جاء، واستبشر به أهل السماء الثانية\n☆تاني\nالطبيعي إن خلاص إحنا عدينا السماء الأولى ومستحيل حد يوصل للسماء الثانية إلا لما يعدي على السماء الأولى، ومفيش حد هيعدي من السماء الأولى إلا لما خزنتها أو حراسها يأذنوا، \nفليه يكون في حراس على كل سماء كده \nثم دي السماء يعني عند ربنا هو مين إللي هيتجرأ إنه يوصل للسماء أصلا\n كل ده يفهمنا معنى كلام ربنا :\n\"فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ فِي يَوْمَيْنِ وَأَوْحَىٰ فِي كُلِّ سَمَاءٍ أَمْرَهَا\"\n فكل سماء منفصلة عن الثانية، كل سماء لها حراسها وأهلها وحياة تانية مختلفة ، ونظام محكم\n سبحان الله، الواحد منبهر بس من مجرد القراءة فما بالكم باللي كان بيشوف الأحداث دي ﷺ \nدخل رسول السماء الثانية فلقى بيستقبله يحي و عيسى ابني الخالة عليهما السلام \nلا بجد متخيلين موقف رسول الله ﷺ  لما يقابل يحيى إللي ربنا أخبره قصته في القرآن \nمتخيلين رسول الله بيستعيد الآيات وجبريل عليه السلام بيعرفه عليهم وبيقول له: \n هذا يحيى وهذا عيسى سلم عليهم !\nيحيى إللي جاء لزكريا على كِبر... يحيى إللي ربنا قال له : خذ الكتاب بقوة ...إللي ربنا قال عنه :\n وحنانا من لدنا وزكاة وكان تقيا\n ولا عيسى عليه السلام ...بيقابله بروحه وجسده ..عيسى المعجزة إللي اتولد من غيرأب ...عيسى إللي رُفع وإللي هينزل في آخر الزمان\n دخل عليهم ورحبوا به قالوا لرسول الله ﷺ:\n مرحبا بالأخ الصالح والنبي الصالح\nشوفوا رسول الله ﷺ  بيوصف لنا شكل عيسى عشان لما ينزل نعرفه، وبيعيشنا معاه وسط الأحداث \nبيقول عنه إنه طوله معتدل لا هو قصير ولا طويل، وشه أبيض مِحْمر شعره ناعم جدا لدرجة إن إللي يشوف شعره يفكر إن عليه مية، عارفين الشعر السايح ده إللي بنقول عليه شعر دهني... هو ده\nلما بيوطي رأسه تحس إن في مية بتنزل من رأسه،\n ترك رسول الله السماء الثانية وطلع للسماء الثالثة ،\nوبرده جبريل خبط على باب من أبواب السماء ورد عليه الخازن نفس الحوار متكرر في السبع سماوات ونفس الإستقبال من كل أهل سماء\nوكان الله بيقول لرسول الله ﷺ  بطريقة عملية لو أهل  الطائف طردوك فأهل السماء بيرحبوا بك ، وطبعا مفيش مقارنة بينهم أصلا\n تعتقدوا رسول الله لسه في قلبه حزن أو ألم، هو فاكر أصلا هو حصل معاه إيه في الطائف\n شفتم ربنا لما بيجبر كسر إنسان ولسه \nدخل رسول الله ﷺ  للسماء الثالثة كان في استقباله مييين\n يوسف \n رسول الله يرى أكثر البشر جمالا على الإطلاق \n هو ده يوسف إللي النسوة قطعن أيديهن بسبب جماله،\n هو ده يوسف إللي اتباع بدراهم معدودة ،\nهو ده يوسف الكريم بن الكريم بن الكريم بن الكريم إللي قعد ظلم في السجن سنوات، \nمتخيلين مشاعر رسول الله لما يقابل أصحاب القصص إللي كان بيسمع عنهم \n تخيلوا لو احنا قابلنا رسول الله أو الأنبياء أو الصحابة إللي احنا بنسمع عنهم دول إحساسنا هيبقى إيه\nده لما حد فينا بيحلم بس برسول الله ﷺ  ولا حد م الصحابة بيبقى طاير من الفرحة ده بقى شافهم حقيقي\n يارب لا تحرمنا صحبتهم واحشرنا معهم\n سلّم رسول الله على يوسف عليه السلام فقال له يوسف مرحبا بالأخ الصالح والنبي الصالح ودعا له بخير،\nوانطلق رسول الله ﷺ  مع جبريل للسماء الرابعة وخبط جبريل واستقبل أهل السماء الرابعة رسول الله ﷺ  وكان في استقباله من الأنبياء.....\nهنعرف إن شاء الله الجزء الجاي مين إللي استقبل رسول  الله ﷺ في السماء الرابعة \n♡"}, {"n": 59, "l": "الجزء 33 | الإسراء والمعراج | المعراج الجزء الثاني", "u": "https://www.facebook.com/groups/710210019782034/permalink/917961055673595/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الثالثة_والثلاثون\n#رحلة_الإسراء_والمعراج_الجزء_الثالث\n#المعراج_الجزء_الثاني\nكان واقفين المرة إللي فاتت مع رسول الله ﷺ  لما دخل السماء الرابعة ورحب به أهلها، \nوجد في استقباله فيها من الأنبياء إدريس عليه السلام،\nفقال جبريل لرسول الله ﷺ هذا إدريس سلّم عليه، فسلم عليه رسول الله ﷺ فقال له إدريس: مرحبا بالأخ الصالح والنبي الصالح!\nواحنا اتكلمنا في قصة إدريس عليه السلام إن ربنا رفعه مكانا عليا\n☆ممكن حد يسأل إزاي ربنا رفعه مكان عليّا وفي أنبياء مكانتهم أعلى منه \nالمعنى المقصود إن ربنا قبض روحه في السماء الرابعة،وهو البشر الوحيد إللي قُبضت روحه في السماء زي ما العلماء بيقولوا\nبعد ما سلّم على رسول الله ﷺ ودعا له بخير، كمّل رسول الله ﷺ  رحلته للسماء الخامسة، \nطلع رسول الله ﷺ السلمة الأولى والثانية والثالثة وبعدها كان على باب من أبواب السماء الخامسة مع جبريل، \nيخبط على الباب والخازن بيسأل مين، وجبريل عليه السلام يرد ويقول جبريل ، والخازن يسأله معاك مين، يقول له جبريل : محمد فيسأل الخازن هو أُرسل إليه فجبريل يقول له : نعم!\n فيقول الخازن فلنعم المجيء جاء ويفرح به أهل السماء ﷺ \n احنا ممكن نفكر إن عشان رسول الله ﷺ  بينتقل من سماء لسماء بثلاث سلمات فقط يبقى المسافة بين السماوات وبعضها مسافة بسيطة\nلأ ده الفرق بين كل سماء والثانية مسيرة خمسمائة عام\nوالمسافة من الأرض لحد ربنا فوق السماء السابعة بتستغرق خمسين ألف سنة \nومع ذلك رسول الله ﷺ كان بيقطع المسافات دي في لحظات فتخيلوا السرعة إللي كان بيتحرك بها رسول الله ﷺ\nبعد ما دخل رسول الله ﷺ السماء لقى في استقباله هارون عليه السلام \n هارون أخو موسى...هارون الرقيق ...هارون الهِبة إللي ربنا وهبها لموسى عليه السلام... هارون وزير موسى عليه... هارون إللي عانى من بنى إسرائيل مع موسى عليه السلام\nفقال جبريل لرسول الله ﷺ هذا هارون سلّم عليه ،فسلم رسول الله ﷺ عليه، فقال له هارون عليه السلام مرحبا بالأخ الصالح والنبي الصالح ! ودعا له هارون عليه السلام بخير،\nوانطلق رسول الله ﷺ  لحد ما وصل للسماء السادسة وخبطوا عليها وحصل نفس الاستئذان ونفس الترحيب برسول الله، \nولقى مين نازل له من السماء السابعة مخصوص عشان يستقبله في السماء السادسة \nموسى عليه السلام \nموسى بني إسرائيل ...موسى الخضر...فاكرين\nجبريل عليه السلام بيقول لرسول الله ﷺ: هذا موسى سلّم عليه!\n تخيلوا رسول الله لما سلّم كان إحساسه إيه\n إحساسه وهو بيتذكر موسى لما كان رضيع وأمه خافت عليه من جنود فرعون، وألقته في البحر،\nموسى إللي اتربى في قصر فرعون... موسى إللي ربنا قال له ولتُصنع على عينى ، إللي ربنا قال له وألقيت عليك محبة مني،\nموسى ...هو ده موسى \nرسول الله بيوصف لنا موسى عليه السلام بيقول إنه كان رجل طويل قليل اللحم يعني رفيع،\n ممشوق الجسم بشرته سمراء شعره لا هو ناعم أوي ولا هو مجعد،\n عارفين الرجال إللي بيكونوا طوال وعندهم عضلات مع جسم متناسق مش العضلات الضخمة دي \nلأ...رجل رفيع طويل قوي عنده عضلات متناسقة مع جسمه\n سلّم عليه رسول الله ﷺ  فقال له موسى مرحبا بالنبي الصالح والأخ الصالح !ودعا له بخير، \nفلما تركه رسول الله ﷺ ومشي مع جبريل بكى موسى عليه السلام \n فسأله الله عز وجل: بتبكي ليه؟ وهو أعلم سبحانه،\n فقال موسى عليه السلام :\nعشان في غلام جاء بعدي وهيدخل الجنة من أمته أكثر من إللي هيدخلها من أمتي \n☆ليه موسى عليه السلام قال كده \nموسى عليه السلام مقلش الكلام ده حسد لرسول الله ﷺ  حاشاه\nده من أولي العزم من الرسل ومعصوم \n بكاؤه كان بكاء حزن على بني إسرائيل وتكذيبهم له مع إنه قعد معاهم سنين طويلة أكثر من إللي رسول الله ﷺ قعدها مع أمته ،\nحتى لما موسى عليه السلام قال غلام، هو كان يقصد صِغر سن رسول الله ﷺ بالنسبة له وللأنبياء من قبله،\n لأننا لو قسنا عمر رسول الله ﷺ بالنسبة لعمر موسى وإبراهيم ونوح هنلاقيه إنه أصغر منهم بكثير \nو مع ذلك ربنا أعطاه ما لم يعط أحد قبله على صِغر سنه ده وقِصر مدة بعثته ﷺ،\n مش إن موسى عليه السلام يقصد التقليل من شأن رسول الله ﷺ  بقوله عنه غلام \nده موسى يا جماعة \nوصل رسول الله ﷺ  للسماء السابعة مع جبريل عليه السلام ودخلوها ورحب أهلها برسول الله ﷺ  لقى فيها إبراهيم عليه السلام \nإبراهيم خليل الله ...إبراهيم إللي أُلقِي في النار...إبراهيم صاحب الدين الحنيف...إبراهيم إللي بنى الكعبة إللى قريش ملتها بالأصنام \nإبراهيم جد رسول الله ﷺ  أبو الأنبياء\nلقاه رسول الله ﷺ قاعد ساند ظهره للبيت المعمور ،\nوالبيت المعمور هو كعبة أهل السماء،\n مكانه فوق الكعبة بالضبط لدرجة إنه لو وقع هيقع على الكعبة،\nفإبراهيم عليه السماء كان قاعد ساند ظهره للبيت المعمور، موقف رهيب طبعا \nوأظن إن ده أكثر مكان مناسب لإبراهيم عليه السلام ،يعني هو ده أكثر مكان ملائم له\nلأن إللي بنى بيت الله في الأرض الطبيعي إنه يكون قاعد عند بيته في السماء\n لا ..وجملة ساند ظهره دي تحسسنا بقمة الإسترخاء \nالواحد يتخيل نفسه كده يسند ظهره للكعبة، إحساس لا يمكن وصفه \nإبراهيم عليه السلام بقى في السماء السابعة قاعد وساند ظهره كده للبيت المعمور إللي بيطوف به كل يوم سبعين ألف ملك لا يعودون إلى يوم القيامة،\nفتخيلوا قمة الإحساس بالأمان مع قمة الإسترخاء \n☆يارب لا تحرمنا\nقال جبريل عليه السلام لرسول الله ﷺ هذا أبوك إبراهيم سلّم عليه!\n فسلّم رسول الله ﷺ  على إبراهيم عليه السلام ،وقال له إبراهيم :\nمرحبا بالابن الصالح والنبي الصالح! ودعا له بخير، وقال لرسول الله ﷺ رسالة يوصلها لكل واحد فينا.. قال :\nسلّم على أمتك وقل لهم :\nالجنة أرض واسعة فاضية ...تربتها خصبة وماؤها عذب، فاللي عايز يزرعها ويغرس فيها نخل وحدائق يقول :\n\"سبحان الله والحمد لله ولا إله إلا الله والله أكبر\"\n◇يعني بالبلدي كده\n إبراهيم عليه السلام بيسلم عليكم يا جماعة وبيقول لكم :\n الجنة أرض زراعية خصبة وواسعة عشان تزرعوها مش محتاجين غير إنكم تقولوا الباقايات الصالحات إللي هي سبحان الله والحمد لله ولا إله إلا الله والله أكبر \nلو واحد فينا أمه أو أبوه وصّوه وصية هيعملها ولا هيكبّر دماغه ويطنش \nأكيد هيعملها \nيبقى ننفذ وصية إبراهيم عليه السلام، ودايما نقول الباقيات الصالحات \nوعارفين بقى \nإللي بيغرس حاجة في الجنة هياكل منها أكيد\nفازرعوا كثير عشان تضمنوا إنكم هتدخلوا الجنة في يوم من الأيام \nرسول الله ﷺ  بيوصف للصحابة شكل إبراهيم عليه السلام وبيقول لهم: \nأشبه واحد بإبراهيم عليه السلام هو صاحبكم..يعني رسول الله ﷺ ! فرسول الله أشد الناس شبه بإبراهيم عليه السلام،\n☆طيب هو رسول الله ﷺ شكله إيه \n هنعرف وصف شكله إن شاء الله لما ييجي وقته \n☆لو ركزنا كده هنلاقي إن الأنبياء كلهم كانوا بيقولوا لرسول الله ﷺ  الأخ الصالح ما عدا إبراهيم وآدم\nوده لأن الأنبياء إللي رسول الله ﷺ  قابلهم كانوا من سُلالة إسحاق بن إبراهيم عليه السلام، \nورسول الله من سلالة إسماعيل عليه السلام فهم يعتبروا أبناء أعمامه، أما آدم وإبراهيم عليهما السلام فهما أبوان لرسول الله ﷺ\nبعد ما رسول الله ﷺ  ترك إبراهيم عليه السلام ذهب مع  جبريل وطلع لِمَا بعد السماء السابعة ووصل لسدرة المنتهى، يعني المكان إللي محدش يقدر يعديه خلاص،\nده أقصى مكان ممكن الملائكة يوصلوا له..... سدرة المنتهى، وفي المكان ده إللي هو فوق السماء السابعة وتحت العرش موجود فيه جنة المأوى،\n الجنة إللي هيدخلها المؤمنون،ربنا يجعلنا جميعا منهم \nسدرة المنتهى دي عبارة عن شجرة السدر إللي هو النّبق، يقول العلماء إن أصلها في السماء السادسة... الجذر والساق يعني في السماء السادسة ،\nوثمارها وأوراقها إللي هو رأس الشجرة موجود فوق السماء السابعة،\nواحنا قلنا من شوية إن الفرق بين كل سماء والثانية خمسمائة عام، فتخيلوا حجم الشجرة عامل إزاي \nبيوصفها رسول الله بيقول إن نبقها يعني ثمرة النبق بتاعها عاملة زي القُلة ، وورق الشجر بتاعها عامل زي أذان الفيلة، يعني ورقة شجرها تشبه أذن الفيل \nرسول الله ﷺ بيربط لنا بين الأشكال عشان نتصور معاه المنظر إللي شافه \nفوهو بينظر لها فجأة يغطيها فَراش من الذهب، فراش مخلوق من الذهب\nفشكلها يتغير لأجمل ما يكون \nوشجرة السدر تعتبر شجر عادية بالنسبة لأشجار ثانية ،\nيعني في شجر أجمل منها، وثماره أحلى من ثمر النبق، \nلكن ربنا اختار شجرة السدر بالذات عشان يثبت قدرته للخلق، \nرسول الله ﷺ انبهر بجمالها لدرجة إنه مبقاش قادر يوصف شدة جمالها مع إنه هو أفصح الخلق\nفقمة الإعجاز الحقيقي يكون في تحويل شجرة عادية الناس متاخدش بالها منها لشجرة في منتهى الجمال، محدش يقدر يوصفها\nفهو سبحانه القادر على تحويل الشيء لعكسه\nعارفين زي إيه عشان المعنى يبان أكثر \nربنا بيقول في القرآن: \n\"الَّذِي جَعَلَ لَكُم مِّنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا أَنتُم مِّنْهُ تُوقِدُونَ\"\nتخيلوا الشجر الأخضر إللي شايفينه ده إللي مليان مية يتحول لنار محرقة \nفده بيدل على قدرة الله إللي ملهاش حدود\nوعند سدرة المنتهى تحصل آية من آيات الله عز وجل رسول الله ﷺ يرى جبريل عليه السلام في صورته الملائكية له ستمائة جناح \nهو كان الفترة دي كلها وخلال العشر سنين إللي فاتوا لما كان يأتي لرسول الله ﷺ كان يتمثل في صورة بشر، \nحتى لما طلع معاه للسماء كان ماشي مع رسول الله ﷺ  بصورته البشرية، \nلحد ما وصل سدرة المنتهى... ظهرت صورته الحقيقية ،وكان بيسقط من أجنحته عليه السلام الدّر والياقوت \n\"وَلَقَدْ رَآهُ نَزْلَةً أُخْرَىٰ ۩ عِندَ سِدْرَةِ الْمُنتَهَىٰ\"\n☆ مثال تقريبي للمعنى \nشوفوا لما الحمام بيرفرف مش بينزل منه ريش بسيط كده، أهه جبريل عليه السلام كان بيسقط من أجنحته الياقوت، حاجة كده خيال فعلا \n لما وصل رسول الله ﷺ لسدرة المنتهى سمع صوت أقلام الملائكة وهم بيكتبوا الأمور التي قضاها الله وبيسجلوها،\nأيوة عندهم أقلام وأوراق وبيكتبوا وصوت أقلامهم مسموع عادي جدا \nمش لازم الأوراق والأقلام زي إللي عندنا بالضبط \nالأسماء متشابهة عادي بس ممكن يكون الشكل مختلف لكنه بيؤدي نفس الغرض وده إللي يهمنا \nيعني هي رجل الكرسي زي رجل البشر\nلأ...لكن الأسماء متشابهة والُإثنين بيؤدوا نفس الهدف، وكل دي من أمور الغيب إللي لازم نؤمن بها\nفي الوقت ده كان جاء موسى عليه السلام،  وشاف إن رسول الله ﷺ  تخطاه في المكانة، \nفقال لربنا : \nيارب أنا متوقعتش إن يُرفع علي أحد !\nهو قال كده لأنه كان وصل لمنزلة سماع أصوات أقلام الملائكة القريبة من سدرة المنتهى ، وهو له مكانة خاصة ، فهو كان عارف لحد اللحظة دي إن مفيش أحد في العالم الأخروي أعلى مكانة منه\nلأنه كليم الله، يعنى ربنا كلم موسى عليه السلام وهو في الدنيا أكثر من مرة، حتى بداية الوحي مكنتش عن طريق جبريل زي باقي الأنبياء لأ.. ده ربنا سبحانه وتعالى هو إللي كلّمه وكلّفه بالرسالة، \nفمكانة موسى عليه السلام عالية جدا، فهو تعجّب إن في أحد وصلت مكانته لأعلى من كده \nفيكون إللي وصل لمنطقة سماع أصوات أقلام الملائكة وهم بيكتبوا اثنان:  موسى عليه السلام ومحمد ﷺ ، ومش بس كده\nده رسول الله ﷺ  هيتخطى المرحلة دي، وهيقابل رب العالمين \nإيه إللي ربنا هيقوله لرسوله ﷺ؟\nوهل رسول الله شاف ربنا ولّا لأ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله في رحلتنا مع رسول الله ﷺ"}, {"n": 60, "l": "الجزء 34 | الإسراء والمعراج | المعراج الجزء الثالث | الجنه ولقاء الله", "u": "https://www.facebook.com/groups/710210019782034/permalink/780904759379226/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والثلاثون\n#رحلة_الإسراء_والمعراج \n#المعراج_الجزء_الثالث\n#الجنة_ولقاء_الله\nاتكلمنا المرة إللي فاتت عن رسول الله ﷺ  لما أخذه جبريل عليه السلام وصعد به فوق السماء السابعة عند سدرة المنتهى، \n وقلنا إن رسول الله ﷺ  رأى جبريل على صورته الحقيقية عند سدرة المنتهى ودي كانت المرة الثانية التى رأى فيها رسول الله ﷺ  جبريل على صورته الملائكية، \n\"وَلَقَدْ رَآهُ نَزْلَةً أُخْرَىٰ ۩ عِندَ سِدْرَةِ الْمُنتَهَىٰ \"\nالمرة الأولى لما جاءه بالوحي بعد فترة الوحي واحنا اتكلمنا عنها قبل كده\nوقلنا كمان إن سدرة المنتهى فوق السماء السابعة وعندها جنة المأوى، \nجبريل عليه السلام أخذ رسول الله ﷺ عشان يقابل ربنا، في الطريق ربنا أهدى رسول الله ﷺ هدية لم يهدها لأي بشر أبدا، \nوهنشوف هدايا كثيرة ربنا أعطاها لرسول الله ﷺ  في الرحلة دي، \nأول هدية إنه جعله يدخل الجنة، وهو مازال على قيد الحياة فرسول الله ﷺ هوالبشري الوحيد إللي دخل الجنة وهو من أهل الدنيا\nجبريل عليه السلام أخذ رسول الله ﷺ  في جولة داخل الجنة، وعايزاكم تتصوروا لما رسول الله ﷺ  يقف على باب الجنة قبل ما يدخلها\n الجنة إللي حكى عنها للصحابة ، الجنة إللي هيدخلها الذين سعدوا\n\"وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالأَرْضُ\"\n تخيلوا موقف رسول الله وهو بيستعيد آيات القرآن عن الجنة :\n\"تِلْكَ الْجَنَّةُ الَّتِي نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا\"\nالجنة إللي هيسكنها المؤمنون للأبد، مفيش بعدها موت، \nالجنة إللي فيها ما لا عين رأت ولاأذن سمعت ولا خطر على قلب بشر،\n الجنة دي رسول الله ﷺ  هيشوفها دلوقتي، ياترى شكلها إيه\n خلونا نشوف رسول الله ص وهو بيوصف لنا الشكل للعام للجنة، بيقول إنه أدخل الجنة، والجنة لها ثمانية أبواب بالمناسبة \n وعرضها كعرض السماوات والأرض ...سبع سماوات وسبع أراضين واخدين بالكم\n أول ما رسول الله دخل شاف حبائل لؤلؤ معلقة،\n عارفين لما بِنُزيّن البيت بشرائط ملونة مدلدلة من السقف في المناسبات كده \n أهه حبائل اللؤلؤ  نفس الفكرة تقريبا \n وشاف قباب من اللؤلؤ ، يعني قبة جنب قبة من اللؤلؤ، \nبص في الأرض لقى الأرض بيضاء ترابها المسك والزعفران وده يدينا انطباع أد إيه ريحة الجنة رائعة\n البيوت شافها مبنية طوبة من الذهب وطوبة من الفضة والمونة إللي بينهم يعني الأسمنت إللي بين الطوب من المسك، \nوالحصى والرمل الواقع في الأرض من اللؤلؤ والياقوت، ده كان المشهد العام للجنة، ربنا يرزقنا الجنة وإياكم \nرسول الله هيبدأ يشرح لنا تفاصيل أدق عن بعض أجزاء الجنة إللي جبريل عليه السلام هيأخذه فيها\n☆ثواني كده...هو  إزاي الجنة فيها ما لاعين رأت ورسول الله ﷺ  شافها أهه\nالمقصود هو إن محدش شاف مثلها أبدا ، مش إن مفيش حد شافها\nيعني مش المعنى إن الجنة مقفول عليها ولم ترها الأعين أبدا،\nلأ... المقصود إن محدش شاف زيها ، وإلا فآدم عليه السلام كان عايش فيها قبل نزوله للأرض ، ورسول الله دخلها وشافها\nمشي رسول الله ﷺ  مع جبريل عليه السلام فشاف نهر، \nلكن النهر ده مش بيتحرك في مجرى مائي زي الأنهار العادية، ده بيتحرك على أرض الجنة\nيعني رسول الله شايف أرض النهر القاع يعني لدرجة إن رسول الله ص مسك الطين إللي في أرض النهر لقاه مسك\n والحصى إللي في قعر النهر ده من اللؤلؤ والياقوت، \nوالنهر كان لونه أبيض من الثلج وطعمه أحلى من العسل،\nعلى حافتين النهر يعني على جوانبه في قصور جميلة على شكل قباب، \nكل قبة عبارة عن لؤلؤة ضخمة مجوفة، المنظر رائع جدا\n رسول الله ﷺ  سأل جبريل عليه السلام قال له:\nإيه ده يا جبريل؟!!\nقال له جبريل عليه السلام هذا نهر الكوثر!\nالنهر إللي ربنا أعطاه لرسول الله ﷺ  \nوالعرب بتستعمل كلمة الكوثر لما يكونوا عايزين يعبروا عن الشيء الكثير، فنهر الكوثر ده ميته كثيرة وأكوابه كثيرة بعدد نجوم السماء \nونهر الكوثر رآه رسول الله ﷺ  في السماء الدنيا مع نهر النيل والفرات فهو منبعه من الجنة وبيجري عبر السماوات ،\nلكنه لا ينزل إلى الأرض زي النيل والفرات إللي اتكلمنا عنهم المرة إللي فاتت\n \nونهر الكوثر هو إللي هيُمِد حوض رسول الله ﷺ  بالماء إللي هيشرب منه المؤمنون يوم القيامة، وإللي هيشرب منه مش هيعطش تاني أبدا\n☆إيه قصة الحوض ده \n يوم القيامة الشمس هتقرب جدا من الرؤوس والناس هتكون عطشانة جدا ومفيش مية غير إللي موجودة في أحواض الأنبياء ومنهم حوض النبي محمد ﷺ ،\n والحوض ده حجمه كبير جدا مسيرة شهر، مليان مية من نهر الكوثر إللي لونه أبيض من الثلج وطعمه أحلى من العسل،\nعدد الأكواب بتاعته بعدد نجوم السماء زي ما قلنا من شوية\nهيبقى موجود على الأرض المُبدلة\n\" يوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ\"\n الناس بقى هتروح لرسول الله ﷺ عشان يشربوا من الحوض بتاعه، فهيشرب منه المؤمنون المتبعين لرسول الله ﷺ فقط،\nوفي ناس هييجوا يشربوا فهتمنعهم الملائكة فرسول الله ﷺ  هيقول: أُمّتي أُمّتي!!!\nيعني الناس دي من أمتي\n فيُقال لرسول الله ﷺ  إنت متعرفش هم عملوا إيه بعدك ، دول لم يتبعوا سنتك وغيروا فيها\nفساعتها رسول الله ﷺ هيقول سُحْقا يعني بُعداً لمن بدّل بعدي وغيّر، يعني ابعدوا أي أحد غيّر في سنتي ولم يتبعنِ \n¤يبقى نستنتج إن إللي عايز يشرب من حوض رسول الله ﷺ  يَلزم سنته وميبدلش ولا يغير فيها ،وميقعدش يخترع في عبادات واحتفالات رسول الله مقلش عليها\n محدش يا جماعة يعمل أي عبادة غير لما يكون عنده حديث صحيح إن رسول الله ﷺ  عمل العبادة دي\nعارفين ليه \n لأن عشان ربنا يتقبل مننا أعمالنا لازم نكون محققين شرطين الإخلاص يعني إننا نعمل العمل الصالح ده عشان نرضي به ربنا بس\nوالشرط الثاني هو إننا نتبع طريقة رسول الله ﷺ  في عمل العمل ده...قال لك صلي الظهر أربع ركعات تصليها أربعة \nرسول الله ﷺ  كان من سنته إنه يصوم اثنين وخميس من كل أسبوع يبقى نعمل زيه\nمش من سنته إنه يصوم أول رجب، يبقى منخترعش بقى ونصوم أول رجب \nرسول الله كان بيحتفل بعيد الفطر وعيد الأضحى فقط ،مكنش بيحتفل لا بعيد أم ولا عيد ميلاد ولا أي عيد تاني \n☆سامعاكي يا حبيبتي ياللي بتقولي ماهو رسول الله قال إنه بيصوم يوم الإثنين عشان هو يوم اتولد فيه يبقى رسول الله احتفل أهه\n أولا :\nالسبب الرئيسي لصيام رسول الله يوم الاثنين والخميس إن الأعمال بتتعرض على ربنا في اليومين دول فهو بيصومهم عشان فضلهم\nثانيا : \nهو بيصومه شكرا لله إنه اتولد فيه، يعني صيامه ده سبب من الأسباب، ده غير إن صيام رسول الله ﷺ  كان كل أسبوع مش أسبوع أه وأسبوع لأ،\nومش شهر أه وشهر لأ، ولا كل سنة مرة زي الاحتفال بعيد الميلاد ولا عيد الأم ولا عيد زواج ولا أي عيد ثاني وإللي بيكون يوم مخصص من كل سنة\n وده هو إللي مينفعش \n◇ ممكن واحدة تقول وفيها إيه يعني لما أقول لأمي كل سنة وانتي طيبة وأجيب لها هدية ولا أجيب تورتاية اتبسط بها أنا زوجي في عيد زواجنا ، يعني من باب البر وإدخال السرور على مسلم ياشيخة عقدتونا\nيا حبيبة قلبي هو احنا مينفعش نعمل كده في عيد الفطر وعيد الأضحى\nهو الدين بيقولك متبريش أمك ومتدخليش السرور على مسلم\n بالعكس ...عندك أيام السنة كلها اعملي إللي إنتي عايزاه فيها، خلاص يعني محبكتش في الأيام المخصصة دي \nهو احنا يعني ينفع نقرأ الفاتحة بدل التشهد\nهتقولي لأ\n هقولك ليه هي الفاتحة وحشة لا سمح الله دي فضلها عظيم جدا\nهتقولي لي عشان الدين قال لنا إننا نقرأ الفاتحة واحنا واقفين في بداية الصلاة، والتشهد بعد كل ركعتين\nوأنا بقولك أهه ياحبيبتي الدين ده هو هو الدين إللي قال لك إن إنتي معندكيش غير عيدين بس تحتفلي وتعملي فيهم كل إللي إنتي عايزاه \nوشوفي كده الموقف ده لما رسول الله هيهاجر للمدينة زي ما هنشوف بعدين، هيلاقي أهل المدينة عندهم يومين عيد من أيام الجاهلية بيلعبوا فيهم ويستمتعوا،\n بيعملوا حاجات مباحة يعني، فرسول الله قالهم لأ ربنا أبدلكم بأحسن منهما أعطاكم يوم الفطر ويوم الأضحى،\n\"إن الله قد أبدلكم بهما خيرا منهما: يوم الأضحى، ويوم الفطر\"\n الصحابة مقلوش يا رسول الله هو احنا بنعمل حاجة حرام\n ده احنا بنرَفّه عن نفسنا بالحلال، هو ليه التعقيد والتشدد ده\nالصحابة قالوا سمعنا وأطعنا ومحدش فيهم عمل أي مظهر من مظاهر الإحتفال في اليومين دول تاني، لا تهنئة ولا جابوا تورتة ولا جابوا هدايا ولا أي حاجة\n طبعا إللي مش مقتنع بالكلام ومش عايز ينفذ هو حر\n بس ميجيش يزعل لما الملائكة تمنعه من الشرب من حوض رسول الله ﷺ، ولا يتقهر لما رسول الله يقول له سُحقا لمن بدّل بعدي وغيّر\n وساعتها مش هيبقى في رجوع تاني للدنيا عشان يصلح غلطه \nاحنا لسه فيها أهه وعندنا فرصة لاتباع سنة رسول الله ﷺ  بالضبط \nخليكم فاكرين كلامي عشان لما نتقابل على الحوض إن شاء الله ونشرب منه ونشوف الناس إللي مسمعتش الكلام والملائكة أبعدتها ،ساعتها نقول الحمد لله إن ربنا هدانا لاتباع سنة رسول الله ﷺ \n استمر رسول الله يمشي في الجنة مع جبريل لحد ما شاف قصر من ذهب ، فرسول الله  ﷺ ظن إن القصر ده بتاعه فسأل جبريل عليه السلام : هو القصر ده بتاع مين؟!\nفقال جبريل: لفتى من قريش ، قال رسول الله أنا من قريش، لمين القصر ده؟!\n قال : لعمر بن الخطاب\n ربنا جهز لعمر قصر في الجنة وهو لسه في الدنيا\n☆طيب احنا كمان عايزين يكون لنا بيت في الجنة واحنا لسه في الدنيا نعمل إيه\nبكل بساطة نصلي السنن الإثنا عشرة ركعة وربنا هيبني لنا بيت في الجنة\nوطبعا بعد بناء البيت محتاجين شوية زرع وشجر ونخيل حول البيت \nفهنقول وصية إبراهيم عليه السلام :\nسبحان الله والحمد لله ولا إله إلا الله والله أكبر، وعندنا من قال: سبحان الله وبحمده غُرست له نخلة في الجنة، \nوعندنا لا حول ولا قوة إلا بالله كنز من كنوز الجنة، \n،يبقى بنينا البيت وزرعنا حوله الحديقة وحطينا فيها الكنوز شوفتم الموضوع سهل إزاي\nورسول الله ﷺ  ماشي مع جبريل عليه السلام شم رائحة جميلة \nاحنا قلنا إن الجنة ريحتها رائعة فتخيلوا الرائحة إللي رسول الله ﷺ  شمها وغطت على ريحة الجنة عاملة إزاي\nفسأل رسول الله ﷺ سأل جبريل إيه الريحة دي؟!\n فقال له جبريل عليه السلام: هذه رائحة ماشطة بنت فرعون وأبنائها!\n♡أنا مجربتهوش بس أكيد إحساس رائع إن الإنسان يكون عنده صديق من الملائكة، ويجاوبه على كل أسئلته كده\n رسول الله ﷺ  سأل جبريل وإيه حكاية ماشطة بنت فرعون وأبنائها دي؟!!\nفحكى له جبريل عليه السلام حكاية الماشطة\nفاكرييين الحكاية \n☆ إللي ميعرفش الحكاية يرجع لقصص الأنبياء في الجزء التاسع والعشرون وهو هيعرف إيه هي قصة ماشطة بنت فرعون وأبنائها\nلما كان رسول الله ﷺ  في الجنة جاؤه جبريل عليه السلام بثلاثة كؤوس واحد فيه لبن وواحد فيه خمر وواحد فيه عسل، \nوالمرة دي الوضع مختلف\n المرة الأولى لما كان في بيت المقدس كان عشان رسول الله عطشان وكان عايز يشرب فجاءه رسول الله بكأس لبن وكأس خمر، \nالمرة دي جبريل عليه السلام جاءه بالكؤوس على سبيل الضيافة يعني \nفاختار رسول الله ﷺ  اللبن ، فقال جبريل عليه السلام: هُديت إلى الفطرة\n خرج رسول الله ﷺ  من الجنة عشان يروح يقابل ربنا عز وجل،\n في الطريق شاف تاني سدرة المنتهى إللي اتكلمنا عنها المرة إللى فاتت وقلنا إن غطتها فراشات من ذهب فتحول شكلها لمنظر لا يستطيع أي مخلوق وصفه من شدة جماله\n المرة دي شافها رسول الله ﷺ وهي بيغطيها ألوان، لكن مش الألوان بتاعتنا المعروفة، رسول الله ﷺ قال إنه ميعرفش إيه الألوان دي \n وطبعا من شدة جمالها ملهاش وصف \nوالحاجات إللي بتغطي سدرة المنتهى متغيرة ، يعني ربنا بيقول :\n\"إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَىٰ\"\n يعني كل شوية حاجة جديدة بتغطيها ، عارفين زي إيه كمثال تقريبي للمعنى\nعارفين الأضواء إللي بتتعلق عالشجر أو على البنايات أو الأضواء إللي بتتعلق كزينة في رمضان وكل شوية الأضواء تتغير بشكل معين شكله حلو \nأهه سدرة المنتهى بتتغير كل شوية بما يريد الله، وطبعا مفيش مقارنة بقى في الجمال ، ربنا يرزقنا جميعا الجنة يارب \nرسول الله ﷺ  رايح دلوقتي لمقابلة رب العالمين\n فأخذه جبريل عليه السلام لفوق سدرة المنتهى لمكان لم يصله بشر أبدا\n وبعدين توقف جبريل عليه السلام وقال لرسول الله ﷺ  إنه يتقدم لوحده \n في هنا رواية بتقول إن رسول الله ﷺ  قال لجبريل أَهُنا يترك الخليل خليله، فقال جبريل لكل منا مقام معلوم ولو تقدمت خطوة لاحترقت، \nفرسول الله تقدم وقال التحيات لله والصلوات والطيبات فربنا قال له السلام عليك أيها النبي إلى آخر الرواية...\n الرواية دي مكذوبة لا تصح عن رسول الله إطلاقا ولو حد بعت لكم رسالة بالكلام ده قولوا إنه مكذوب لا يصح عن رسول الله ﷺ \nالصحيح بقى إن جبريل توقف في مكان معين من الرحلة لأنه مش مسموح له إنه يتخطى المكان ده، وسمح لرسول الله ﷺ  إنه يتقدم للقاء الله في مكان لم يصل إليه أحد حتى من الملائكة\nفين المكان ده... الله أعلم، هل احنا في محيط السماء السابعة ولا محيط سدرة المنهى ؟ الله أعلم \n وصل رسول الله ﷺ  لمكان لم يصل إليه ملك ولا بشر قبله، وفي وسط كل الأحداث دي والآيات العظيمة لم يزغ بصر رسول الله ﷺ ، بمعنى مش احنا لما بنشوف حاجة جديدة جميلة أو بنروح مكان جديد لأول مرة بنقعد  نبص يمين وشمال نستكشف المكان \nرسول الله ﷺ  معملش كده، كان مركز في لقائه مع الله ، وإللي بيقول كده ربنا عز وجل :\n\" مَا زَاغَ الْبَصَرُ وَمَا طَغَىٰ ۩  لَقَدْ رَأَىٰ مِنْ آيَاتِ رَبِّهِ الْكُبْرَىٰ \"\n☆شوفوا... احنا بنوصف موقف، لكن رسول الله ﷺ  إللي كان في الموقف نفسه مشاعره كانت إيه، قلبه كان بيدق إزاي كان بيفكر في إيه محدش يقدر يتخيل الموقف ده أبدا\n لو دخلنا على ملك ولا رئيس من رؤساء الدنيا ولا بس بيبقى عندنا مقابلة مع حد مهم بيبقى شعورنا إيه\nبلاش دي\n البنات لما بتكون عندها رؤية شرعية والعريس جاي بتبقى عاملة إزاي\n رسول الله ﷺ  واقف هيكلم رب العالمين في مكان لم يصل له بشر ولا ملك، مفيش أي كلمات تقدر توصف الموقف ده\n كلم رب العالمين رسول الله ﷺ، وربنا بيتكلم يا جماعة عادي ، واحنا ونثبت له صفة الكلام زي ماهو قال عن نفسه، لكن منعرفش هو بيتكلم إزاي ولا صوته إيه\n هنعرف في الجنة إن شاء الله \n كل الترحيب ده وتقريب رسول الله ﷺ لمكان لم يصل إليه بشر ولا ملك عشان كلمة رسول الله ﷺ  قالها، وهو في شدة همه وألمه وبكاؤه والدم بينزف منه:\n\"إن لم يكن بك غضب علي فلا أبالي\"\n يعني يارب لو إنت راضي عني و مش غضبان علي فأنا معنديش مشكلة أهم حاجة إنك تكون راضي عني \n واحنا عندنا في قوانين البشر بنقول إن الأفعال أصدق من الأقوال، \nولله المثل الأعلى في السماوات والأرض ربنا أراد إنه يُرِي رسول الله ﷺ  بطريقة عملية أد إيه هو راضي عنه\nفقربه إليه في المكان ده\nربنا كلم رسول الله ﷺ  وأعطاه هديتين وأمره بأمر،\n الهدية الأولى إللي ربنا أهداها لرسول الله ﷺ كانت خواتيم سورة البقرة إللي هي:\n \"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۩\nلَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ \nرَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ۩ \n☆قبل ما نقول فضل الآيتين دول خلينا نوضح نقطة مهمة وهي إن ربنا أه أعطى رسول الله خواتيم سورة البقرة لكن هي لسه مش هتنزل على المؤمنين دلوقتي\n يعني ربنا قال لرسول الله إنه أعطاه خواتيم سورة البقرة، إيه هي الآيات دي وتفصيلها إيه؟  لسه مش هتنزل دلوقتي ، هتنزل على رسول الله ﷺ  لما ييجي وقتها أو يحصل سبب نزولها وهنعرفه إن شاء الله بعدين\nنشوف إيه فضل الآيات دس مع رسول الله ﷺ \nمن يقرأ خواتيم سورة البقرة في كل ليلة قبل ما ينام كَفَتَاه، يعني:\n♡تُجزئه عن قيام الليل \n♡تجزئه عن قراءة القرآن بشكل عام\n♡تكفيان الإنسان من كل سوء\n♡تكفيان من الثواب، يعني تحقق لنا من الثواب إللي يعادل سيئات اليوم\n كل ده تفسير العلماء لحديث رسول الله ﷺ :\n\"منْ قَرَأَ بالآيتَيْنِ مِنْ آخِرِ سُورةِ البقَرةِ فِي لَيْلَةٍ كَفَتَاهُ\"\nوشوفوا الحديث ده:\n\" إِنَّ اللَّهَ كَتَبَ كِتَابًا قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ بِأَلْفَيْ عَامٍ ،\nفَأَنْزَلَ مِنْهُ آيَتَيْنِ فَخَتَمَ بِهِمَا سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏وَلَا يُقْرَآنِ فِي دَارٍ ثَلَاثَ لَيَالٍ فَيَقْرَبَهَا الشَّيْطَانُ\"\nالأجر ده كله بآيتين فقط \nيا جماعة دين ربنا سهل بس احنا إللي بنصعب على نفسنا \n الشيطان ييجي يقولك لازم تقرإي سورة البقرة كلها كل يوم، ولا لازم أقرأ ثلاثة أجزاء ولا جزئين في اليوم والموضوع صعب عليكي،\n فتلاقي نفسك سيبتي قراءة القرآن خالص\n طيب ليه مناخدش الحاجات السهلة البسيطة إللي أجرها عالي لحد نثبت نفسنا عليها وتبقى جزء من حياتنا اليومية وبعدين نزود \nيعني النهاردة عرفنا إزاي نبني بيت في الجنة وعرفنا إزاي نزرع نخل وشجر ويكون عندنا كنوز في الجنة وعرفنا خواتيم سورة البقرة،\n منقدرش نعمل الحاجات البسيطة دي كل يوم ونداوم عليها ؟\n نقدر إن شاء الله\n فضل ربنا واسع والأعمال سهلة بس احنا نبدأ\n☆قبل ما نشوف الهدية الثانية... في سؤال مهم لازم نجاوب عليه، هو رسول الله ﷺ  شاف ربنا\nباختصار القول الراجح من أقوال العلماء بالاعتماد على الدليل الشرعي،\nهو إن لا رسول الله ﷺ ولا حتى الملائكة شافوا ربنا، ومحدش هيشوف ربنا قبل يوم القيامة ،\nو الدليل لما سُئل رسول الله ﷺ  : هل رأيت ربك؟  قال : نور أنّى أراه\"\nأما الملائكة فمفيش أي دليل على إنه في حد فيهم رأى الله عز وجل، بالعكس الأدلة بتقول إنهم لم يروه في الحديث: \n\" إِنَّ اللهَ عَزَّ وَجَلَّ لَا يَنَامُ، وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ،\n يَخْفِضُ الْقِسْطَ وَيَرْفَعُهُ، يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ، وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ، \nحِجَابُهُ النُّورُ - وَفِي رِوَايَةِ أَبِي بَكْرٍ: النَّارُ - لَوْ كَشَفَهُ لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ\"\nفالمؤمنين هيشوفوا ربنا في الجنة ، \nالهدية الثانية إللي أعطاها ربنا لرسول الله ﷺ  كانت........\nهنعرف إن شاء الله المرة الجاية"}, {"n": 61, "l": "الجزء 35 | الإسراء والمعراج | المعراج الجزء الرابع | فرض الصلاه", "u": "https://www.facebook.com/groups/710210019782034/permalink/780917369377965/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والثلاثون\n#رحلة_الإسراء_والمعراج \n#المعراج_الجزء_الرابع\n#الصلاة\nاتكلمنا  المرة إللي فاتت عن الهدايا إللي ربنا أعطاها لرسول الله ﷺ  وقلنا عن إن أول هدية كانت خواتيم سورة البقرة واتكلمنا عن فضلهم كان إيه، \nالنهاردة هنتكلم عن الهدية الثانية وهي:\n《 غفران المُقْحِمات لمن لم يشرك بالله شيئا》 \nبراحة كده عشان الكلام ده مهم \nالمُقْحِمات هي كبائر الذنوب زي الزنا والسرقة وغيرها من الكبائر،\n واسمها مُقْحِمات لأنها بِتُقْحم الإنسان في النار ، يعني بتزقه وتوقعه في النار\n فمعنى الكلام بوجه عام : \nإن ربنا هيغفر لأصحاب الكبائر ماداموا ماتوا على التوحيد ولم يشركوا بالله شيئا ومعاهم لا إله إلا الله ، حتى من غير ما يتعذبوا ، يعني من مات على كبيرة وهو لا يشرك بالله شيئا ربنا هيغفر له ويدخله الجنة\nحلو الكلام  لحد كده \nالكلام ده\n بقى هل هو لكوووول الناس\n لأ مش لكل الناس ، في ناس من أصحاب الكبائر لو ماتوا على التوحيد ربنا هيعذبهم على قدر ذنوبهم في النار وبعدين يخرجهم من النار ويدخلهم الجنة\nيبقى هنطلع بالكلام ده بقاعدتين مهمتين\n◇ الأولى :\nإن من مات من المسلمين على كبيرة من الكبائر من غير ما يتوب منها ،\nفهو في مشيئة ربنا إذا شاء عذبه وإذا شاء غفر له وأدخله الجنة من غير ما يتعذب في النار خالص، \nودي حاجة ربنا هو إللي هيحددها بعلمه بقلوب العباد، مين يستحق إنه يتغفر له ومين يستحق العذاب على الكبائر إللي عملها قبل ما يدخل الجنة\n◇القاعدة الثانية: \nإن أهل الكبائر من أمة الإسلام إذا دخلوا النار عشان يتعذبوا لا يُخلدوا في النار، \nيعني مادام الإنسان مات وهو على الإسلام وحتى لو معملش خير أبدا لن يُخلد في النار مادام معاه لا إله إلا الله\nهيتعذب على قدر ذنوبه ويخرج من النار ويدخل الجنة، مادام لا يشرك بالله شيئا ومعاه التوحيد يعني معاه لا إله إلا الله، \nوالكلام ده كله موجود في الأحاديث الصحيحة عن رسول الله ﷺ \nشوفتم رحمة ربنا واسعة إزاي \n☆ بس استنواااا \n عشان محدش بقى ياخد الكلام ويروح يعمل إللي هو عايزه ويقول عادي بقى مانا ربنا هيغفرلي أو يقول أتعذب شوية وبعدين أدخل الجنة \n مين إللي يضمن إنه يموت على الإسلام من غير ما يشرك بالله شيئا \nالمعاصي بريد الكفر، يعني إللي يداوم على المعصية وهو حاببها ومش فارق معاه حاجة ومبسوط بيها ومش في دماغه توبة ولا كره للمعصية، ده يتخاف عليه إنه يستحل المعصية، و إللي يستحل المعصية يبقى كافر، والكافر لا يدخل الجنة\nمعادلة صعبة صح\n ربنا أعطانا هدية قال : إللي فيكم هيموت على التوحيد هيدخل الجنة و إن زنى وإن سرق ،\n لكن مين بقى إللي يضمن إنه يموت على التوحيد\n وخصوصا إن الشيطان بيكون أشد ما يكون إغواء وفتنة على بني  آدم عند الموت،\n بيقول لأعوانه إلحقوه قبل ما روحه تطلع خلوه يكفر لأنكم لو ملحقتهوش خلاص طلع من تحت إيدكم \n فالشيطان حريص جدا إنه يفتن الناس حتى عند الموت، ورسول الله نفسه كان بيقول :\n\" اللهم إني أعوذ بك أن يتخبطني الشيطان عند الموت\"\n تخيلوا رسول الله كان بيقول كده فاحنا بقى نقول إيه\nعشان كده رسول الله علمنا إننا بعد التشهد الأخير نقول:\n اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ ، \nوَمِنْ عَذَابِ الْقَبْرِ ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ\" \nففتنة الممات هي فتنة الشيطان للإنسان عند الموت،\n فمين بقى يضمن إنه لو عاش على عمل الكبائر بحجة إن ربنا بيغفر لأهل الكبائر ماداموا بيقولوا لا إله إلا الله إنه يموت على الإسلام والشيطان لا يفتنه \n نحس كده إن الناس دي بالمنظر ده هيكونوا قليلين\nلكن مع ذلك ربنا طمنهم وطمنا إن متقلقوش أهم حاجة إنكم تموتوا على التوحيد، ومن عاش على التوحيد وقول لا إله إلا الله هيموت عليها أكيد\nدي كانت الهدية الثانية لأمة الإسلام، \nمع الهدايا ربنا أمر رسول الله ﷺ  بأمر واجب التنفيذ،\n وده الأمر الوحيد إللي ربنا أمر بيه في المكان ده، \nكل أوامر وشرائع الإسلام ربنا أمر بها أو نهى عنها عن طريق جبريل عليه السلام ورسول الله  ﷺ في الأرض إلا الأمر ده،  وأكيد الموضوع له معنى وحكمة\n احنا عارفين إن ربنا عز وجل لا يفعل أي شيء عبث، \nكل حاجة لها حكمة، فمعنى إنه يأمر بالأمر ده في المكان ده يبقى أكيييد الأمر ده مهم جدا \n خلونا نقرب المعنى شوية \nولله المثل الأعلى في السماوات والأرض، \nلما أمك أو أبوكي أو زوجك أو مديرك في العمل أو أي حد يطلب منك حاجة عن طريق إنه يرسل لك شخص ويقولك اعملي كذا، \nزوجك يبعتلك ابنك، أمك تقولك يا فلانة اعملي كذا أو تبعتلك أختك تقولك ماما بتقولك اعملي كذا ، \nهل هيكون انطباعك في الكلام إللي وصل لك، زي ما والدتك تبعتلك وتقولك تعالي أنا عايزاكي،\n ولما تروحي لها تقوم واخداكي وداخلة أوضة وقافلة عليكي وعليها الباب وتتأكد إن مفيش حد معاكم \nمش بتحسي إنها عايزة تقولك حاجة مهمة وبتبقي متأهبة ومستعدة للكلام إللي هيتقال، وإنك لازم هتعملي إللي هتقولك عليه\n♧ ما علينا إنها مبتطلعش حاجة مهمة في الآخر بس أنا بتكلم عالإحساس\n ولله المثل الأعلى، أهه ربنا أحضر رسول الله ﷺ  في المكان ده إكراما له وكمان عشان يقول له بنفسه الأمر المهم ده\nربنا أمر رسول الله ﷺ  وأمة الإسلام بإنهم يصلوا لله في اليوم والليلة خمسين صلاة \n رسول الله ﷺ أخذ الأمر من ربنا من غير ما يعترض ولا يسأل على أي حاجة ونزل لجبريل عليه السلام عشان يرجعه للأرض بقى والرحلة تنتهي\n لكن حصلت حاجة غيرت الحوار كله \n قابل رسول الله ﷺ  موسى عليه السلام في السماء السابعة فسأله : بماذا أمرت؟ يعني ربنا أمرك بإيه؟ \nوموسى عليه السلام مسألش رسول الله ﷺ  هل ربنا أمرك بشيء ولا لأ، \nلأن موسى عليه السلام عارف إن مادام رسول الله راح يقابل ربنا يبقى أكيد هيفرض على أمته شيء \nماهو موسى عليه السلام خبير \n مين إللي راح قابل ربنا وأعطاه الله الألواح\n فموسى عليه السلام توقع إن ربنا أمره بحاجة عشان كده سأله على طول بم أمرت، وكان توقعه في محله \nفسأل رسول الله ﷺ  ربنا أمرك بإيه؟ \nقال له رسول الله ﷺ: أمرني ربي بخمسين صلاة في اليوم والليلة!\n فقال له موسى عليه السلام : أمتك مش هتطيق الخمسين صلاة دي ،وأنا مجرب بني إسرائيل قبلك فارجع لربك واسأله التخفيف!!!\n¤لازم نقف هنا وقفة مهمة جدا \nفاكرييين موسى عليه السلام قال إيه لما رسول الله ﷺ  سلم عليه في السماء السادسة وبعدها سابه ومشي مع جبريل عليه السلام \nبكى موسى عليه السلام، ولما ربنا سأله ما يبكيك قال غلام يُبعث بعدي يدخل من أمته الجنة أكثر من أمتي،\n وقلنا إن موسى عليه السلام لم يقصد حسدا ولم يقصد إنه يقلل من شأن رسول الله ﷺ وهنا يبان الدليل \n، لو كان موسى عليه السلام في قلبه شيء على رسول الله ﷺ أو أمة الإسلام كان استغل الفرصة،\n وقال كده أمة محمد لن تطيق الخمسين صلاة وهيعصوا ربنا وربنا يدخلهم النار وبكده تكون أمتي أكثر من أمة محمد في الجنة \nلكن حاشاه عليه السلام إن يكون ده تفكيره، بالعكس ده هو يريد الخير لرسول الله ﷺ  ولأمته \nوطبعا ييجي هنا دور الخبرة \n موسى عليه السلام عانى مع بني إسرائيل أشد المعاناة واحنا شفنا إللي كانوا بيعملوه مع موسى عليه السلام لحد ما كلنا  تقريبا اتنقطنا منهم\n فهو عليه السلام  بيعطي رسول الله ﷺ  الخلاصة عشان هو عايز الناس تطيع ربنا، وهو عارف طبائع الناس عاملة إزاي،\nعشان كده رسول الله ﷺ  لم يُشكك في كلامه لما قال له يسأل ربنا التخفيف ، \nرسول الله ﷺ  نظر لجبريل ..يعني بيسأله هو ينفع أرجع أسأل ربنا التخفيف؟ \nمقلهوش هو الكلام إللي بيقوله موسى صحيح ولا ولأ ، هو واثق فيه \n☆ورسول الله ﷺ  بيعلمنا درس مهم جدا هنا وهتلاقي الناس مفتقدينه جدا في حياتهم،\n وهو تقبل النصيحة من إللي أقل مننا في المنزلة أو العلم\nإزاي \nإنتم متفقين معايا إن محمد ﷺ  أفضل من موسى عليه السلام ومنزلته أعلى صح\nومع ذلك بقى رسول الله ﷺ  تقبل نصيحة موسى عليه السلام لأن هو عنده الخبرة \nفموسى عليه السلام يعتبر النبي الوحيد قبل رسول الله إللي قاد قومه من البداية،\n يعني خرج من مصر مع بني إسرائيل وراحوا قعدوا في صحراء سيناء ، فهو كان يحكم بني إسرائيل من مرحلة الصفر، \nزي ما رسول الله  ﷺ  بدأ مع المسلمين من مرحلة الصفر لحد ما هيبني دولة ويكون هو حاكمها\n عشان كده هنلاقي إن أكثر الأنبياء ربنا ذكره في القرآن هو موسى عليه السلام عشان رسول الله ﷺ  يستفيد من خبرته \nطبعا بخلاف داوود وسليمان عليهما السلام وضعهم بالنسبة لرسول الله وموسى عليه السلام مختلف لأنهم كانوا ملوك\nرسول الله ﷺ  أخذ بنصيحة موسى عليه السلام ومقلش مثلا زي ماناس في واقعنا بتقول : وإنت مين قالك إن أمتى هتبقى زي أمتك \nمش عشان يعني أمتك غلطت وإنت مكنتش عارف تتعامل معاهم يبقى لازم يكون الوضع معايا هو هو\nولا أنا أعلى منك منزلة فأكيد أمتي هتكون مختلفة \n☆وده يعلمنا إن لما حد من أصحاب الخبرة الثقة ينصحونا نأخذ بنصيحتهم، ونبطل فلسفة \nرسول الله ﷺ  سأل جبريل عليه السلام ينفع يا جبريل أسأل ربنا التخفيف ولا لأ ؟!\nجبريل قال له عادي تسأل ربنا مفيش مشكلة لو عايز،\n فرجع رسول الله ﷺ  لرب العزة وسأله التخفيف في الصلاة، \nففعلا ربنا خفف عنه عشر صلوات ، وفي رواية تانية خمسة وأصبحت الصلاة أربعين صلاة،\n ونزل رسول الله ﷺ وقابله موسى عليه السلام وسأله عملت إيه؟\n قال  رسول الله ﷺ أمرني ربي بأربعين صلاة!!\n فقال له موسى عليه السلام : أمتك مش هتقدر ، أنا مجرب بني إسرائيل قبلك، اسأل ربك التخفيف\n فرجع رسول الله ﷺ  وسأل ربنا التخفيف ،فخفف الله عنه عشر وأصبحت ثلاثين،\n واستمر موسى عليه السلام يقول لرسول الله ﷺ  اسأل ربك التخفيف لحد ما وصلوا لخمس صلوات، \nفقال له موسى عليه السلام أمتك لن تطيق اسأل ربك التخفيف،\n فرسول الله ﷺ قال : أنا استحييت من كثرة ما طلبت من ربنا التخفيف، \nفقال الله عز وجل : هم خمس صلوات في اليوم والليلة ، لكل صلاة عشر فيكونوا خمسون صلاة،\n ومن هَمّ بحسنة يعني نوى يعمل حسنة فلم يعملها تُكتب له حسنة، ولو عملها تكتب له عشر حسنات ، \nومن هَمّ بسيئة فلم يعملها لا تُكتب عليه شيء، ولو عملها تكتب سيئة واحدة، ودي من هدايا للرحمن للأمة \n◇تخيلوا بقى بعد ده كله في ناس يوم القيامة ميزان سيئاتها هو إللي هيرجح\nالمهم يبقى آخر الكلام إن الصلاة خمسة في العمل وخمسون في الأجر، \nجبريل عليه السلام أخذ رسول الله ﷺ  ونزل به من السماء إلى الأرض في رحلة العودة\n☆إيه ده هو فين نوح عليه السلام\n مش هو من أولي العزم من الرسل ورسول الله ص قابل كل أولي العزم\nالعلماء قالوا إن دي ليلة رحمة، فكان المناسب إن رسول الله ﷺ  لا يرى من هلك قومه بالعذاب ، زي نوح ومن شابهه من الأنبياء زي هود وصالح عليهم جميعا السلام\n وطبعا ده يقودنا إلى أن وجود الأنبياء في سماء مختلفة مش معناه إن دي منزلتهم عند ربنا \nهم خرجوا من الجنة عشان يستقبلوا رسول الله ﷺ  ، ففي منهم إللي أسرع عشان يقابله وفيه منهم إللي تأخر، \nوإلا فإن عيسى عليه السلام أفضل من يوسف عليه السلام لأن عيسى من أولي العزم ومع ذلك عيسى كان في السماء الثانية ويوسف كان في السماء الثالثة\n احنا طبعا عندنا أسئلة كثيرة عن أحداث فرض الصلاة \nزي هل المسلمون قبل فرض الصلوات الخمس كانوا بيصلوا ولا لأ؟ \nوليه ربنا فرض في الأول الصلاة خمسين صلاة مادام هو هيخففها لخمسة بعد كده؟\nواشمعنا ربنا اختار الصلاة ليفرضها فوق سبع سماوات؟ \nوليه ربنا اختار موسى عليه السلام بالذات عشان يقوم بمهمة مراجعة رسول الله ص في موضوع الصلاة؟\n واشمعنى رسول الله استحى من مراجعة ربنا في التخفيف عند الخمسة مش قبلها؟ \nإجابة الأسئلة دي هنعرفها الجزء الجاي إن شاء الله"}, {"n": 62, "l": "الجزء 36 | الإسراء والمعراج | المعراج الجزء الخامس | نهاية المعراج", "u": "https://www.facebook.com/groups/710210019782034/permalink/780928829376819/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والثلاثون\n#رحلة_الإسراء_والمعراج \n#المعراج_الجزء_الخامس\n#نهاية_المعراج\nاتكلمنا المرة إللي فاتت عن رسول الله ﷺ  لما طلب من ربنا التخفيف في الصلاة زي ما موسى عليه السلام قال له، \nوربنا فعلا خفف الصلاة من خمسين صلاة لخمس صلوات في اليوم والليلة،\nوقلنا كم سؤال محتاجين نجاوب عليهم\n◇السؤال الأول :\nهل كان المسلمون قبل فرض الصلوات الخمس بيصلوا ولا لأ\nخلاصة القول في الموضوع ده إن الصلاة كانت مفروضة من أول بعثة رسول الله ﷺ،  \nوكانت صلاة قيام الليل مفروضة على رسول الله ﷺ  وعلى المسلمين في أول سنة من البعثة،\n وبعدين نُسخت وبقت الصلاة المفروضة ركعتين في أول النهار وركعتين في أخره، زي ما قلنا قبل كده\n وجبريل عليه السلام كان علم رسول الله  ﷺ كيفية الوضوء وكيفية الصلاة منذ البداية ،\nوبعدين علمه أوقات الصلاة إللي احنا دلوقتي، \nأما بالنسبة للأذان فلسه لم يُشرع دلوقتي، قصادنا كم سنة كده على ما يُشرع الأذان وله قصة هنقولها في وقتها إن شاء الله \nوالخمس صلوات إللي ربنا فرضهم دول هيكونوا ركعتين فقط، وبعدين لما رسول الله ﷺ  يهاجر ، \nهتزيد ...الظهر والعصر والعشاء هيكونوا أربعة والمغرب ثلاثة،ولما يكون المسلمون على سفر هيقصروا الصلاة الرباعية فقط\n◇السؤال الثاني: \nليه ربنا فرض في الأول خمسين صلاة مادام هو هيخففها لخمس صلوات بعدين، يعني كان فرض الخمس صلوات من البداية وخلاص\nاحنا عارفين إن ربنا لا يكلف نفسا إلا وسعها \nومعنى إن ربنا يفرض علينا خمسين صلاة في اليوم والليلة فده معناه إننا نقدر نصلي الخمسين صلاة دي \nهو أه هنقعد طول اليوم كله نصلي\n بس مفيش مشكلة، أصلا ربنا خلقنا للعبادة فطبيعي إننا نقضي اليوم كله في الصلاة \n فعشان ربنا يُرِي الناس رحمته بهم  قدّر إنهم يكونوا خمسين وبعدين يتخففوا لخمس صلوات في اليوم والليلة،\n ومش بس كده ده أعطانا أجر الخمسين كامل\nفتخيلوا بقى الناس إللي بتفرط ومقصرة في الخمس صلوات مع إنهم يقدروا يصلوا خمسين صلاة ده وضعهم هيبقى إيه عند ربنا\n وطبعا ده يشجعنا إننا مش بس نحافظ على الخمس صلوات، لا ده احنا كمان نحافظ على السنن الإثنا عشرة ركعة\n☆وبما إننا بنتكلم على الصلاة والسنن ففي معلومة مهمة محتاجين نعرفها\nوهي إن أول ما يحاسب عليه العبد يوم القيامة الصلاة...إذا صَلُحَتْ فَقَدْ أَفْلَحَ وَأَنْجَحَ،\n وَإِنْ فَسَدَتْ فَقَدْ خَابَ وَخَسِرَ \nيعني لازم نجيب في امتحان الصلاة عشرة من عشرة\nطيب إزاي هنجيب عشرة من عشرة وفي شيطان إسمه خنزب وظيفته بس إنه يُلهي الإنسان عن الخشوع  في الصلاة ويسرق منها ويخلينا نسرح ونفكر في حاجات برة الصلاة \nحتى شوفوا حديث رسول الله ﷺ :  \nإنه ليس للعبد من صلاته إلا ما عَقل منها، \nإن العبد يقوم في الصلاة لا يُكتب له منها إلا نصفها.. إلا ثلثها.. إلا ربعها.. إلا خمسها، حتى قال: إلا عشرها.\nكده هيبقى مستحيل إنا ننجح في إمتحان الصلاة ،و هنلاقي إننا طالعين خسرانين وممكن صلاتنا كده تضيع \nطب إيه الحل\n هنا بقى تيجي رحمة ربنا \n \nالحل في قول ربنا في الحديث القدسي للملائكة :\n\" انْظُرُوا هَلْ لِعَبْدِي مِنْ تَطَوُّعٍ ؟ فَإِنْ كَانَ لَهُ تَطَوُّعٌ ،\n قَالَ: أَتِمُّوا لِعَبْدِي فَرِيضَتَهُ مِنْ تَطَوُّعِهِ\"\n يعني ربنا هيقول للملائكة يوم القيامة شوفوا عبدي لو عنده أي تطوع كملوا به النقص في الصلاة، \nيعني السنن الرواتب يُكَمّل بها ما نَقص من الفريضة\nفلو الإنسان كان بيصلي سنن يبقى هو عنده مخزون يقدر يكمل منه، \nطيب لو مكنش بيصلي السنن ، أنا مش هقول إنتم تصوروا الموقف إللي ممكن يكون فيه ساعتها\n فمش معقول بعد كل رحمة ربنا دي نقصر في الصلاة، وخصوصا إننا أصلا نقدر نصلي الخمسين صلاة\nيعني لو أحد من البشر عمل فينا معروف بنبقى ممتنين جدا له، فما بالكم بربنا إللي خلق لنا الجنة وأنزل علينا من رحماته\n◇ندخل في السؤال الثالث \n اشمعنا ربنا اختار الصلاة بالذات عشان يفرضها من فوق سبع سماوات؟\n احنا قلنا إن الصلاة مهمة وهي الشريعة الوحيدة إللي ربنا أمر بها فوق سبع سماوات في مكان خاص جدا \nليه بقى الخصوصية والأهمية دي\nربنا أراد إنه يعطي المسلمين حاجة تَصِلهم به تُشبه ولو من بعيد إللي حصل مع رسول الله ﷺ \nخلونا نوضح أكثر، تعالوا نستعيد كده رحلة الإسراء والمعراج من البداية\n جبريل عليه السلام غسل قلب وجوف رسول الله  ﷺ  قبل ما يبتدي رحلة لقاء ربنا، \nمش احنا برده قبل ما نقابل ربنا في الصلاة بنتوضأ والوضوء ده بيغسل السيئات بتاعتنا قبل ما ندخل في الصلاة \nوبعدين رسول الله وهو رايح للقاء الله عدّى على الجنة،\nمش احنا برده بعد ما نتوضأ بنقول:\n\" اللهم اجعلني من التوابين واجعلني من المتطهرين ، أشهد ألا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله \" وهنا أبواب الجنة بتتفتح لنا \nرسول الله ﷺ  طلع لوحده لمقابلة ربنا وتكلم معاه، واحنا برده لما بنصلي بنكون قصاد ربنا ولوحدنا وبنتكلم معاه وهو بيرد علينا \nشوفوا ربنا بيقول إيه الحديث القدسي ،\nبيقول إنه قسم الصلاة بينه وبين عبده نصفين، \nيعني لما الواحد فينا بيصلي ويقرأ الفاتحة ويقول: \"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\"\n ربنا بيقول : حمدني عبدي، ولما يقول: \"الرَّحْمَنِ الرَّحِيمِ \" يقول الله : أثنى علي عبدي، ، \nولما يقول العبد : \"مَالِكِ يَوْمِ الدِّينِ\" ربنا يقول : مجّدني عبدي،\n فإذا قال : \"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ  \"ربنا يقول:\n هذا بيني وبين عبدي، \nفإذا قال : \"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ *صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ\"\nقال الله : هذا لعبدي ولعبدي ما سأل،\n فتخيلوا لما كل صلاة نفتكر قصة الإسراء والمعراج ونشعر كده إننا بنكلم ربنا ، أكيد هيبقى في خشوع وهنحقق الغاية من الصلاة، وهي:\n \"وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ\" \n                                                                    \n◇نيجي للسؤال الرابع:\n ليه ربنا اختار موسى عليه السلام بالذات بمهمة مراجعة رسول الله  ﷺ  في موضوع الصلاة \nشوفوا...موسى عليه السلام نشعر كده إنه غير كل الأنبياء خصوصا مع ربنا \nيعني لما رمى الألواح في الأرض إللي فيها كلام ربنا، وشد رأس نبي من الأنبياء ولحيته وجره إليه من شدة غضبه ،\nربنا لم يعاتبه \n ودايما نحس منه بجرأة في الكلام مع ربنا، يعني لما قال لربنا لما رسول الله اترفع لمكانة أعلى منه:\n يارب أنا لم أظن إنك هترفع علي أحد !!\n في المكانة يعني ، فهو حاسس إنه له مكانة مميزة عند ربنا وخصوصا إن هو النبي الوحيد إللي ربنا كلمه على الأرض أكثر من مرة ،\n بعكس رسول الله ﷺ  ربنا كلمه في السماء، وبعكس آدم عليه السلام ربنا برده كلمه في السماء، \nحتى بداية الوحي ربنا كلم موسى عليه السلام مباشرة، \nلم يرسل له جبريل عليه السلام زي باقي الأنبياء ،\nعشان كده هو اسمه كليم الله\nفهنحس معاه كده زي الناس إللي في قلبها على لسانها \nيعني لما خاف طلع يجري ، \nولما خاف مرة تانية قال لربنا أنا خايف، فموسى عليه السلام نشعر إن هو النبي الوحيد إللي عنده الجرأة إنه يتكلم ويشجع رسول الله ﷺ  إنه يسأل التخفيف من ربنا \nفطبيعة الأنبياء التسليم المُطلق لله بدون سؤال أو إعطاء رأي، بعكس موسى عليه السلام وطبيعته المختلفة نلاقيه بيعرض رأيه على ربنا عادي جدا، وربنا بيقبل منه بسبب مكانته\nفعشان كده ربنا وضع موسى عليه السلام بالذات في طريق رسول الله ﷺ  وخصوصا إن موسى عليه السلام عنده الخبرة زي ما قلنا المرة إللي فاتت\n فهو أكثر واحد يقدر يفيد رسول الله ﷺ ، وكمان موسى عليه السلام حالته فريدة من نوعها\n يعني الأنبياء كانوا بيعانوا من المكذبين فقط من قومهم، موسى عليه السلام كان بيعاني من المكذبين والمؤمنين به زي ما شفنا  في قصته ،\nفاكرين لما موسى عليه السلام اختار أربعين رجل لميقات الله ،والمفروض إنهم أحسن ناس في بني إسرائيل وفي الآخر قالوا أرنا الله جهرة\nلما دول أحسن ناس فيهم أمال الباقيين عاملين إزاي، \nفكل الأسباب دي وغيرها جعلت موسى عليه السلام هو الشخص المناسب للمهمة دي\n¤وده يقودنا لسؤال مهم جدا \nوهو إزاي موسى عليه السلام يعترض أصلا ويطلب من رسول الله ﷺ  إنه يسأل من ربنا التخفيف مع إنه هو إللي  قال لبني إسرائيل افعلوا ما تؤمرون لما قال لهم إن ربنا يأمركم أن تذبحوا بقرة\nاحنا قلنا من شوية إن من صفات الأنبياء ومنهم موسى عليه السلام التسليم التام لأوامر الله، \nومش معنى إن موسى عليه السلام بيقول رأيه في مواقف معينة يبقى هو كده معترض أو لا ينفذ أوامر الله حاشاه \nالعلماء لهم قولين في السبب إللي جعل موسى عليه السلام يقول رأيه ورسول الله ﷺ  يسمع كلامه  :\nالقول الأول:\n إن موسى عليه السلام ورسول الله ﷺ  كانوا عارفين إن فرض الخمسين صلاة ده مش أمر حتمي غير قابل للنقاش،\n لا هم كانوا عارفين إن الأمر لسه فيه كلام عشان كده موسى عليه السلام قال رأيه ،\nورسول الله ﷺ  أخذ برأيه وأيده جبريل عليه السلام، والملائكة لا يفعلون أمر إلا بإذن الله فكان واضح إن الموضوع لسه فيه كلام\nالقول الثاني للعلماء : \nإن ده كان من باب سؤال الله التخفيف ورفع الحرج والمشقة عن الأمة ، وده جائز لا يتنافى مع الرضا بقضاء الله ولا التسليم له،\nزي بالضبط لما ندعي ربنا برفع البلاء، والنصر على الأعداء، فالدعاء بالتخفيف والرحمة من الله مختلف تماما عن إللي بني إسرائيل عملوه \nده قعدوا يشددوا على نفسهم وربنا يشدد عليهم، فرحمة بيهم عشان ميشددوش على نفسهم أكثر من كده ،موسى عليه السلام قال لهم افعلوا ما تؤمرون\n♡بالمناسبة موسى عليه السلام لم يتمنّ إنه يكون من أمة محمد \nكل الأحاديث إللي بتقول عن موسى عليه السلام إنه تمنى يكون من أمة محمد فهي إما أحاديث موضوعة أو منكرة ضعيفة جدا لا تصح \n◇نيجي لآخر سؤال وهو : \nاشمعنى رسول الله ﷺ  استحى في مراجعة ربنا لما وصل  للصلوات الخمس ومستحاش قبل كده\n أولا:\n لازم نعرف إن كل حاجة بتتم بقدر الله \nيعني ربنا أَلهم موسى عليه السلام إنه يقول لرسول الله  ﷺ إنه يسأل ربنا التخفيف، \nوأَلهم رسول الله إنه يسأل الله التخفيف كل مرة وألهمه كذلك الحياء إنه يسأل التخفيف لما وصل للعدد خمس صلوات\nثانيا: \nفي رواية بتقول إن ربنا كان بيخفف الصلوات خمسة خمسة لحد ما وصلت لخمس صلوات ، فلو رسول الله ﷺ  رجع وسأل ربنا التخفيف كده مش هيبقى في صلاة،  وكأن رسول الله ﷺ  بيطلب من ربنا  إلغاء الصلاة \n ده غير إن ربنا كان بيخفف الصلاة من غير ما يُعقب على شيء ، \nلحد ما وصلوا لخمس صلوات فعقّب هنا وقال إنهم خمس في العمل وخمسين في الأجر، فعرف رسول الله ﷺ  إن مينفعش تخفيف أقل من كده\n☆دي كانت معظم الأسئلة إللي ممكن تيجي على بال حد فينا\nكده رحلة رسول الله ﷺ  للسماء انتهت وخلاص هينزل للأرض مع جبريل عليه السلام، نزل رسول الله ﷺ من السماء لبيت المقدس مرة أخرى وركب على البراق عشان يرجع لبيته في مكة\nلكن قبل ما نرجع مع رسول الله ﷺ لمكة ونشوف أبو جهل وباقي كفار قريش تاني\n ونشوف رد فعلهم على قصة الإسراء برسول الله ﷺ، \nفي أحداث حصلت في رحلة الإسراء والمعراج أنا مقلتهاش لأن أنا معرفش وقتها كان إمتى بالضبط هل كان قبل المعراج ولا بعده، لأن العلماء مختلفين فيها، أنا كنت ناوية أذكرها النهاردة،\n بس هخليها للمرة الجاية عشان نفضل عايشين مع رحمة ربنا شوية لأن الشخص إللي رسول الله ﷺ  قابله كان صعب،\nوالحاجات إللي رسول الله ﷺ  شافها كانت أصعب،\nفالموضوع محتاج تفصيل\nرسول الله ﷺ قابل مين، وإيه المشاهد إللي شافها ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
